INSERT INTO spell VALUES (614,'Summon Monster V','summon monster V','Conjuration','Summoning','see text for summon monster I',NULL,'Bard 5, Cleric 5, Sorcerer/Wizard 5','V, S, F/DF','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two of which can be more than 30 ft. apart','1 round/level (D)','None','No','Calls extraplanar creature to fight for you.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 5th-level list, 1d3 creatures of the same kind from the 4th-level list, or 1d4+1 creatures of the same kind from a lower-level list.</p>\n      <p/>\n    ',NULL,'A tiny bag and a small (not necessarily lit) candle.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Monster V\" level=\"5\"><p><h5>Summon Monster V</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [see text for summon monster I]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Cleric 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One or more summoned creatures, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 5th-level list, 1d3 creatures of the same kind from the 4th-level list, or 1d4+1 creatures of the same kind from a lower-level list.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
