=\"2\" curcol=\"2\">\n<td>Tojanida, elder<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>9th Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elemental, elder<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Grig [NG; with fiddle] (sprite)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Pixie* (sprite) [NG; with sleep and memory loss arrows]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Unicorn, celestial charger<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>*Can cast <i>irresistible dance</i><br/></td>\n\n</tr>\n\n<tr maxcol=\"2\" curcol=\"2\">\n<td>1 May be summoned only into an aquatic or watery environment.<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Nature\'s Ally IX\" level=\"5\"><p><h5>Summon Nature\'s Ally IX</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [see text]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One or more creatures, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>summon nature\'s ally I</i>,  except that you can summon one 9th-level creature, 1d3 8th-level creatures of the same kind, or 1d4+1 lower-level creatures of the same kind.</p><p>When you use a summoning spell to summon an air, chaotic, earth, evil, fire, good, lawful, or water creature, it is a spell of that type.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>Summon Nature\'s Ally</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>1st Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire rat<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Eagle (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Monkey (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Octopus<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Owl (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Porpoise<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Snake, Small viper (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Wolf (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>2nd Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Bear, black (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Crocodile (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire badger<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire bat<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elemental, Small (any)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Hippogriff<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Shark, Medium<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Snake, Medium viper (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Squid<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Wolverine (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>3rd Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Ape (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire weasel<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire wolf<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Eagle, giant [NG]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Lion<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Owl, giant [NG]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Satyr [CN; without pipes]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Shark, Large<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Snake, constrictor (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Snake, Large viper (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Thoqqua<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>4th Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Arrowhawk, juvenile<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Bear, brown (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Crocodile, giant (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Deinonychus (dinosaur)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire ape<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire boar<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire wolverine<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elemental, Medium (any)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Salamander, flamebrother [NE]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Sea cat<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Shark, Huge<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Snake, Huge viper (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Tiger (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Tojanida, juvenile<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Unicorn [CG]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Xorn, minor<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>5th Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Arrowhawk, adult<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Bear, polar (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire lion<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elasmosaurus<b>1</b> (dinosaur)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elemental, Large (any)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Griffon<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Janni (genie)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Rhinoceros (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Satyr [CN; with pipes]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Snake, giant constrictor (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Nixie (sprite)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Tojanida, adult<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Whale, orca<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>6th Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire bear<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elemental, Huge (any)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elephant (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Girallon<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Megaraptor (dinosaur)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Octopus, giant<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Pixie* (sprite) [NG; no special arrows]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Salamander, average [NE]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Whale, baleen<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Xorn, average<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>*Can\'t cast <i>irresistible dance</i><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>7th Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Arrowhawk, elder<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire tiger<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elemental, greater (any)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Djinni (genie) [NG]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Invisible stalker<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Pixie* (sprite) [NG; with sleep arrows]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Squid, giant<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Triceratops (dinosaur)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Tyrannosaurus (dinosaur)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Whale, cachalot<b>1</b> (animal)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Xorn, elder<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>*Can\'t cast <i>irresistible dance</i><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>8th Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Dire shark<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Roc<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Salamander, noble [NE]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Tojanida, elder<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td><b>9th Level</b><br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Elemental, elder<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Grig [NG; with fiddle] (sprite)<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Pixie* (sprite) [NG; with sleep and memory loss arrows]<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>Unicorn, celestial charger<br/></td>\n\n</tr>\n<tr maxcol=\"2\" curcol=\"2\">\n<td>*Can cast <i>irresistible dance</i><br/></td>\n\n</tr>\n\n<tr maxcol=\"2\" curcol=\"2\">\n<td>1 May be summoned only into an aquatic or watery environment.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (628,'Summon Swarm','summon swarm','Conjuration','Summoning',NULL,NULL,'Bard 2, Druid 2, Sorcerer/Wizard 2','V, S, M/DF','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One swarm of bats, rats, or spiders','Concentration + 2 rounds','None','No','Summons swarm of bats, rats, or spiders.',NULL,NULL,'A square of red cloth.',NULL,'\n      <p>You summon a swarm of bats, rats, or spiders (your choice), which attacks all other creatures within its area. (You may summon the swarm so that it shares the area of other creatures.) If no living creatures are within its area, the swarm attacks or pursues the nearest creature as best it can. The caster has no control over its target or direction of travel.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Swarm\" level=\"5\"><p><h5>Summon Swarm</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Druid 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One swarm of bats, rats, or spiders<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration + 2 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You summon a swarm of bats, rats, or spiders (your choice), which attacks all other creatures within its area. (You may summon the swarm so that it shares the area of other creatures.) If no living creatures are within its area, the swarm attacks or pursues the nearest creature as best it can. The caster has no control over its target or direction of travel.</p><p><i>Arcane Material Component:</i> A square of red cloth.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (629,'Sunbeam','sunbeam','Evocation',NULL,'Light',NULL,'Druid 7, Sun 7','V, S, DF','1 standard action','60 ft.',NULL,'Line from your hand',NULL,'1 round/level or until all beams are exhausted','Reflex negates and Reflex half; see text','Yes','Beam blinds and deals 4d6 damage.',NULL,NULL,NULL,NULL,'\n      <p>For the duration of this spell, you can use a standard action to evoke a dazzling beam of intense light each round. You can call forth one beam per three caster levels (maximum six beams at 18th level). The spell ends when its duration runs out or your allotment of beams is exhausted.</p>\n      <p>Each creature in the beam is blinded and takes 4d6 points of damage. Any creatures to which sunlight is harmful or unnatural take double damage. A successful Reflex save negates the blindness and reduces the damage by half.</p>\n      <p>An undead creature caught within the beam takes 1d6 points of damage per caster level (maximum 20d6), or half damage if a Reflex save is successful. In addition, the beam results in the destruction of any undead creature specifically harmed by bright light if it fails its save.</p>\n      <p>The ultraviolet light generated by the spell deals damage to fungi, mold, oozes, and slimes just as if they were undead creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sunbeam\" level=\"5\"><p><h5>Sunbeam</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Light]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 7, Sun 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Line from your hand<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level or until all beams are exhausted<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates and Reflex half; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>For the duration of this spell, you can use a standard action to evoke a dazzling beam of intense light each round. You can call forth one beam per three caster levels (maximum six beams at 18th level). The spell ends when its duration runs out or your allotment of beams is exhausted.</p><p>Each creature in the beam is blinded and takes 4d6 points of damage. Any creatures to which sunlight is harmful or unnatural take double damage. A successful Reflex save negates the blindness and reduces the damage by half.</p><p>An undead creature caught within the beam takes 1d6 points of damage per caster level (maximum 20d6), or half damage if a Reflex save is successful. In addition, the beam results in the destruction of any undead creature specifically harmed by bright light if it fails its save.</p><p>The ultraviolet light generated by the spell deals damage to fungi, mold, oozes, and slimes just as if they were undead creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (630,'Sunburst','sunburst','Evocation',NULL,'Light',NULL,'Druid 8, Sorcerer/Wizard 8, Sun 8','V, S, M/DF','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'80-ft. -radius burst',NULL,'Instantaneous','Reflex partial; see text','Yes','Blinds all within 10 ft., deals 6d6 damage.',NULL,NULL,'A piece of sunstone and a naked flame.',NULL,'\n      <p><i>Sunburst</i> causes a globe of searing radiance to explode silently from a point you select. All creatures in the globe are blinded and take 6d6 points of damage. A creature to which sunlight is harmful or unnatural takes double damage. A successful Reflex save negates the blindness and reduces the damage by half.</p>\n      <p>An undead creature caught within the globe takes 1d6 points of damage per caster level (maximum 25d6), or half damage if a Reflex save is successful. In addition, the burst results in the destruction of any undead creature specifically harmed by bright light if it fail its save.</p>\n      <p>The ultraviolet light generated by the spell deals damage to fungi, mold, oozes, and slimes just as if they were undead creatures.</p>\n      <p><i>Sunburst</i> dispels any darkness spells of lower than 9th level within its area.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sunburst\" level=\"5\"><p><h5>Sunburst</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Light]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 8, Sorcerer/Wizard 8, Sun 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>80-ft. -radius burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p><i>Sunburst</i> causes a globe of searing radiance to explode silently from a point you select. All creatures in the globe are blinded and take 6d6 points of damage. A creature to which sunlight is harmful or unnatural takes double damage. A successful Reflex save negates the blindness and reduces the damage by half.</p><p>An undead creature caught within the globe takes 1d6 points of damage per caster level (maximum 25d6), or half damage if a Reflex save is successful. In addition, the burst results in the destruction of any undead creature specifically harmed by bright light if it fail its save.</p><p>The ultraviolet light generated by the spell deals damage to fungi, mold, oozes, and slimes just as if they were undead creatures.</p><p><i>Sunburst</i> dispels any darkness spells of lower than 9th level within its area.</p><p><i>Arcane Material Component:</i> A piece of sunstone and a naked flame.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (631,'Symbol of Death','symbol of death','Necromancy',NULL,'Death',NULL,'Cleric 8, Sorcerer/Wizard 8','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Fortitude negates','Yes','Triggered rune slays nearby creatures.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp each.',NULL,NULL,'\n      <p>This spell allows you to scribe a potent rune of power upon a surface. When triggered, a <i>symbol of death</i> slays one or more creatures within 60 feet of the symbol (treat as a burst) whose combined total current hit points do not exceed 150. The <i>symbol of death</i> affects the closest creatures first, skipping creatures with too many hit points to affect. Once triggered, the <i>symbol</i> becomes active and glows, lasting for 10 minutes per caster level or until it has affected 150 hit points\' worth of creatures, whichever comes first. Any creature that enters the area while the <i>symbol of death</i> is active is subject to its effect, whether or not that creature was in the area when it was triggered. A creature need save against the <i>symbol</i> only once as long as it remains within the area, though if it leaves the area and returns while the <i>symbol</i> is still active, it must save again.</p>\n      <p>Until it is triggered, the <i>symbol of death</i> is inactive (though visible and legible at a distance of 60 feet). To be effective, a <i>symbol of death</i> must always be placed in plain sight and in a prominent location. Covering or hiding the rune renders the <i>symbol of death</i> ineffective, unless a creature removes the covering, in which case the <i>symbol of death</i> works normally.</p>\n      <p>As a default, a <i>symbol of death</i> is triggered whenever a creature does one or more of the following, as you select: looks at the rune; reads the rune; touches the rune; passes over the rune; or passes through a portal bearing the rune. Regardless of the trigger method or methods chosen, a creature more than 60 feet from a symbol of death can\'t trigger it (even if it meets one or more of the triggering conditions, such as reading the rune). Once the spell is cast, a <i>symbol of death</i>\'s triggering conditions cannot be changed.</p>\n      <p>In this case, \'reading\' the rune means any attempt to study it, identify it, or fathom its meaning. Throwing a cover over a <i>symbol of death</i> to render it inoperative triggers it if the symbol reacts to touch. You can\'t use a <i>symbol of death</i> offensively; for instance, a touch-triggered symbol of death remains untriggered if an item bearing the <i>symbol of death</i> is used to touch a creature. Likewise, a <i>symbol of death</i> cannot be placed on a weapon and set to activate when the weapon strikes a foe.</p>\n      <p>You can also set special triggering limitations of your own. These can be as simple or elaborate as you desire. Special conditions for triggering a <i>symbol of death</i> can be based on a creature\'s name, identity, or alignment, but otherwise must be based on observable actions or qualities. Intangibles such as level, class, Hit Dice, and hit points don\'t qualify.</p>\n      <p>When scribing a <i>symbol of death</i>, you can specify a password or phrase that prevents a creature using it from triggering the effect. Anyone using the password remains immune to that particular rune\'s effects so long as the creature remains within 60 feet of the rune. If the creature leaves the radius and returns later, it must use the password again.</p>\n      <p>You also can attune any number of creatures to the <i>symbol of death</i>,  but doing this can extend the casting time. Attuning one or two creatures takes negligible time, and attuning a small group (as many as ten creatures) extends the casting time to 1 hour. Attuning a large group (as many as twenty-five creatures) takes 24 hours. Attuning larger groups takes proportionately longer. Any creature attuned to a <i>symbol of death</i> cannot trigger it and is immune to its effects, even if within its radius when triggered. You are automatically considered attuned to your own <i>symbols of death</i>, and thus always ignore the effects and cannot inadvertently trigger them.</p>\n      <p><i>Read magic</i> allows you to identify a <i>symbol of death</i> with a DC 19 Spellcraft check. Of course, if the <i>symbol of death</i> is set to be triggered by reading it, this will trigger the symbol.</p>\n      <p>A <i>symbol of death</i> can be removed by a successful <i>dispel magic</i> targeted solely on the rune. An <i>erase</i> spell has no effect on a <i>symbol of death</i>. Destruction of the surface where a <i>symbol of death</i> is inscribed destroys the <i>symbol</i> but also triggers it.</p>\n      <p><i>symbol of death</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>symbol of death</i> that is disabled or that has affected its maximum number of hit points becomes inactive for 10 minutes, then can be triggered again as normal.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of death</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of death</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 33 for <i>symbol of death</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Death\" level=\"5\"><p><h5>Symbol of Death</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One symbol<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell allows you to scribe a potent rune of power upon a surface. When triggered, a <i>symbol of death</i> slays one or more creatures within 60 feet of the symbol (treat as a burst) whose combined total current hit points do not exceed 150. The <i>symbol of death</i> affects the closest creatures first, skipping creatures with too many hit points to affect. Once triggered, the <i>symbol</i> becomes active and glows, lasting for 10 minutes per caster level or until it has affected 150 hit points\' worth of creatures, whichever comes first. Any creature that enters the area while the <i>symbol of death</i> is active is subject to its effect, whether or not that creature was in the area when it was triggered. A creature need save against the <i>symbol</i> only once as long as it remains within the area, though if it leaves the area and returns while the <i>symbol</i> is still active, it must save again.</p><p>Until it is triggered, the <i>symbol of death</i> is inactive (though visible and legible at a distance of 60 feet). To be effective, a <i>symbol of death</i> must always be placed in plain sight and in a prominent location. Covering or hiding the rune renders the <i>symbol of death</i> ineffective, unless a creature removes the covering, in which case the <i>symbol of death</i> works normally.</p><p>As a default, a <i>symbol of death</i> is triggered whenever a creature does one or more of the following, as you select: looks at the rune; reads the rune; touches the rune; passes over the rune; or passes through a portal bearing the rune. Regardless of the trigger method or methods chosen, a creature more than 60 feet from a symbol of death can\'t trigger it (even if it meets one or more of the triggering conditions, such as reading the rune). Once the spell is cast, a <i>symbol of death</i>\'s triggering conditions cannot be changed.</p><p>In this case, \'reading\' the rune means any attempt to study it, identify it, or fathom its meaning. Throwing a cover over a <i>symbol of death</i> to render it inoperative triggers it if the symbol reacts to touch. You can\'t use a <i>symbol of death</i> offensively; for instance, a touch-triggered symbol of death remains untriggered if an item bearing the <i>symbol of death</i> is used to touch a creature. Likewise, a <i>symbol of death</i> cannot be placed on a weapon and set to activate when the weapon strikes a foe.</p><p>You can also set special triggering limitations of your own. These can be as simple or elaborate as you desire. Special conditions for triggering a <i>symbol of death</i> can be based on a creature\'s name, identity, or alignment, but otherwise must be based on observable actions or qualities. Intangibles such as level, class, Hit Dice, and hit points don\'t qualify.</p><p>When scribing a <i>symbol of death</i>, you can specify a password or phrase that prevents a creature using it from triggering the effect. Anyone using the password remains immune to that particular rune\'s effects so long as the creature remains within 60 feet of the rune. If the creature leaves the radius and returns later, it must use the password again.</p><p>You also can attune any number of creatures to the <i>symbol of death</i>,  but doing this can extend the casting time. Attuning one or two creatures takes negligible time, and attuning a small group (as many as ten creatures) extends the casting time to 1 hour. Attuning a large group (as many as twenty-five creatures) takes 24 hours. Attuning larger groups takes proportionately longer. Any creature attuned to a <i>symbol of death</i> cannot trigger it and is immune to its effects, even if within its radius when triggered. You are automatically considered attuned to your own <i>symbols of death</i>, and thus always ignore the effects and cannot inadvertently trigger them.</p><p><i>Read magic</i> allows you to identify a <i>symbol of death</i> with a DC 19 Spellcraft check. Of course, if the <i>symbol of death</i> is set to be triggered by reading it, this will trigger the symbol.</p><p>A <i>symbol of death</i> can be removed by a successful <i>dispel magic</i> targeted solely on the rune. An <i>erase</i> spell has no effect on a <i>symbol of death</i>. Destruction of the surface where a <i>symbol of death</i> is inscribed destroys the <i>symbol</i> but also triggers it.</p><p><i>symbol of death</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>symbol of death</i> that is disabled or that has affected its maximum number of hit points becomes inactive for 10 minutes, then can be triggered again as normal.</p><p><i>Note:</i> Magic traps such as <i>symbol of death</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of death</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 33 for <i>symbol of death</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp each.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (632,'Symbol of Fear','symbol of fear','Necromancy',NULL,'Fear, Mind-Affecting',NULL,'Cleric 6, Sorcerer/Wizard 6','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Will negates','Yes','Triggered rune panics nearby creatures.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 1,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>symbol of death</i>, except that all creatures within 60 feet of the <i>symbol of fear</i> instead become panicked for 1 round per caster level.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of fear</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of fear</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 31 for <i>symbol of fear</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Fear\" level=\"5\"><p><h5>Symbol of Fear</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Fear, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr></table><p>This spell functions like <i>symbol of death</i>, except that all creatures within 60 feet of the <i>symbol of fear</i> instead become panicked for 1 round per caster level.</p><p><i>Note:</i> Magic traps such as <i>symbol of fear</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of fear</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 31 for <i>symbol of fear</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 1,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (633,'Symbol of Insanity','symbol of insanity','Enchantment','Compulsion','Mind-Affecting',NULL,'Cleric 8, Sorcerer/Wizard 8','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Will negates','Yes','Triggered rune renders nearby creatures insane.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>symbol of death</i>, except that all creatures within the radius of the <i>symbol of insanity</i> instead become permanently insane (as the <i>insanity</i> spell).</p>\n      <p>Unlike <i>symbol of death</i>, symbol of insanity has no hit point limit; once triggered, a <i>symbol of insanity</i> simply remains active for 10 minutes per caster level.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of insanity</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of insanity</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 33 for <i>symbol of insanity</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Insanity\" level=\"5\"><p><h5>Symbol of Insanity</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr></table><p>This spell functions like <i>symbol of death</i>, except that all creatures within the radius of the <i>symbol of insanity</i> instead become permanently insane (as the <i>insanity</i> spell).</p><p>Unlike <i>symbol of death</i>, symbol of insanity has no hit point limit; once triggered, a <i>symbol of insanity</i> simply remains active for 10 minutes per caster level.</p><p><i>Note:</i> Magic traps such as <i>symbol of insanity</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of insanity</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 33 for <i>symbol of insanity</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (634,'Symbol of Pain','symbol of pain','Necromancy',NULL,'Evil',NULL,'Cleric 5, Sorcerer/Wizard 5','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Fortitude negates','Yes','Triggered rune wracks nearby creatures with pain.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 1,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>symbol of death</i>, except that each creature within the radius of a <i>symbol of pain</i> instead suffers wracking pains that impose a -4 penalty on attack rolls, skill checks, and ability checks. These effects last for 1 hour after the creature moves farther than 60 feet from the symbol.</p>\n      <p>Unlike <i>symbol of death</i>, <i>symbol of pain</i> has no hit point limit; once triggered, a <i>symbol of pain</i> simply remains active for 10 minutes per caster level.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of pain</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of pain</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 30 for <i>symbol of pain</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Pain\" level=\"5\"><p><h5>Symbol of Pain</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Sorcerer/Wizard 5<br/></td></tr></table><p>This spell functions like <i>symbol of death</i>, except that each creature within the radius of a <i>symbol of pain</i> instead suffers wracking pains that impose a -4 penalty on attack rolls, skill checks, and ability checks. These effects last for 1 hour after the creature moves farther than 60 feet from the symbol.</p><p>Unlike <i>symbol of death</i>, <i>symbol of pain</i> has no hit point limit; once triggered, a <i>symbol of pain</i> simply remains active for 10 minutes per caster level.</p><p><i>Note:</i> Magic traps such as <i>symbol of pain</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of pain</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 30 for <i>symbol of pain</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 1,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (635,'Symbol of Persuasion','symbol of persuasion','Enchantment','Charm','Mind-Affecting',NULL,'Cleric 6, Sorcerer/Wizard 6','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Will negates','Yes','Triggered rune charms nearby creatures.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>symbol of death</i>, except that all creatures within the radius of a <i>symbol of persuasion</i> instead become <i>charmed</i> by the caster (as the <i>charm monster</i> spell) for 1 hour per caster level.</p>\n      <p>Unlike <i>symbol of death</i>, <i>symbol of persuasion</i> has no hit point limit; once triggered, a <i>symbol of persuasion</i> simply remains active for 10 minutes per caster level.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of persuasion</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of persuasion</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 31 for <i>symbol of persuasion</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Persuasion\" level=\"5\"><p><h5>Symbol of Persuasion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Charm) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr></table><p>This spell functions like <i>symbol of death</i>, except that all creatures within the radius of a <i>symbol of persuasion</i> instead become <i>charmed</i> by the caster (as the <i>charm monster</i> spell) for 1 hour per caster level.</p><p>Unlike <i>symbol of death</i>, <i>symbol of persuasion</i> has no hit point limit; once triggered, a <i>symbol of persuasion</i> simply remains active for 10 minutes per caster level.</p><p><i>Note:</i> Magic traps such as <i>symbol of persuasion</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of persuasion</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 31 for <i>symbol of persuasion</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (636,'Symbol of Sleep','symbol of sleep','Enchantment','Compulsion','Mind-Affecting',NULL,'Cleric 5, Sorcerer/Wizard 5','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Will negates','Yes','Triggered rune puts nearby creatures into catatonic slumber.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 1,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>symbol of death</i>, except that all creatures of 10 HD or less within 60 feet of the <i>symbol of sleep</i> instead fall into a catatonic slumber for 3d6x10 minutes. Unlike with the <i>sleep</i> spell, sleeping creatures cannot be awakened by nonmagical means before this time expires.</p>\n      <p>Unlike <i>symbol of death</i>, <i>symbol of sleep</i> has no hit point limit; once triggered, a <i>symbol of sleep</i> simply remains active for 10 minutes per caster level.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of sleep</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of sleep</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 30 for <i>symbol of sleep</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Sleep\" level=\"5\"><p><h5>Symbol of Sleep</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr></table><p>This spell functions like <i>symbol of death</i>, except that all creatures of 10 HD or less within 60 feet of the <i>symbol of sleep</i> instead fall into a catatonic slumber for 3d6x10 minutes. Unlike with the <i>sleep</i> spell, sleeping creatures cannot be awakened by nonmagical means before this time expires.</p><p>Unlike <i>symbol of death</i>, <i>symbol of sleep</i> has no hit point limit; once triggered, a <i>symbol of sleep</i> simply remains active for 10 minutes per caster level.</p><p><i>Note:</i> Magic traps such as <i>symbol of sleep</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of sleep</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 30 for <i>symbol of sleep</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 1,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (637,'Symbol of Stunning','symbol of stunning','Enchantment','Compulsion','Mind-Affecting',NULL,'Cleric 7, Sorcerer/Wizard 7','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Will negates','Yes','Triggered rune stuns nearby creatures.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>symbol of death</i>, except that all creatures within 60 feet of a <i>symbol of stunning</i> instead become stunned for 1d6 rounds.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of stunning</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of stunning</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 32 for <i>symbol of stunning</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Stunning\" level=\"5\"><p><h5>Symbol of Stunning</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr></table><p>This spell functions like <i>symbol of death</i>, except that all creatures within 60 feet of a <i>symbol of stunning</i> instead become stunned for 1d6 rounds.</p><p><i>Note:</i> Magic traps such as <i>symbol of stunning</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of stunning</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 32 for <i>symbol of stunning</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (638,'Symbol of Weakness','symbol of weakness','Necromancy',NULL,'Death',NULL,'Cleric 7, Sorcerer/Wizard 7','V, S, M','10 minutes','0 ft.; see text',NULL,NULL,'One symbol','See text','Fortitude negates','Yes','Triggered rune weakens nearby creatures.',NULL,'Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>symbol of death</i>, except that every creature within 60 feet of a <i>symbol of weakness</i> instead suffers crippling weakness that deals 3d6 points of Strength damage.</p>\n      <p>Unlike <i>symbol of death</i>, <i>symbol of weakness</i> has no hit point limit; once triggered, a <i>symbol of weakness</i> simply remains active for 10 minutes per caster level.</p>\n      <p><i>Note:</i> Magic traps such as <i>symbol of weakness</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of weakness</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 32 for <i>symbol of weakness</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Symbol of Weakness\" level=\"5\"><p><h5>Symbol of Weakness</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Sorcerer/Wizard 7<br/></td></tr></table><p>This spell functions like <i>symbol of death</i>, except that every creature within 60 feet of a <i>symbol of weakness</i> instead suffers crippling weakness that deals 3d6 points of Strength damage.</p><p>Unlike <i>symbol of death</i>, <i>symbol of weakness</i> has no hit point limit; once triggered, a <i>symbol of weakness</i> simply remains active for 10 minutes per caster level.</p><p><i>Note:</i> Magic traps such as <i>symbol of weakness</i> are hard to detect and disable. A rogue (only) can use the Search skill to find a <i>symbol of weakness</i> and Disable Device to thwart it. The DC in each case is 25 + spell level, or 32 for <i>symbol of weakness</i>.</p><p><i>Material Component:</i> Mercury and phosphorus, plus powdered diamond and opal with a total value of at least 5,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (639,'Sympathetic Vibration','sympathetic vibration','Evocation',NULL,'Sonic',NULL,'Bard 6','V, S, F','10 minutes','Touch','One freestanding structure',NULL,NULL,'Up to 1 round/level','None; see text','Yes','Deals 2d10 damage/round to freestanding structure.',NULL,NULL,NULL,'A tuning fork.','\n      <p>By attuning yourself to a freestanding structure such you can create a damaging vibration within it. Once it begins, the vibration deals 2d10 points of damage per round to the target structure. (Hardness has no effect on the spell\'s damage.) You can choose at the time of casting to limit the duration of the spell; otherwise it lasts for 1 round/level. If the spell is cast upon a target that is not freestanding the surrounding stone dissipates the effect and no damage occurs.</p>\n      <p><i>Sympathetic vibration</i> cannot affect creatures (including constructs). Since a structure is an unattended object, it gets no saving throw to resist the effect.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sympathetic Vibration\" level=\"5\"><p><h5>Sympathetic Vibration</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One freestanding structure<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Up to 1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>By attuning yourself to a freestanding structure such you can create a damaging vibration within it. Once it begins, the vibration deals 2d10 points of damage per round to the target structure. (Hardness has no effect on the spell\'s damage.) You can choose at the time of casting to limit the duration of the spell; otherwise it lasts for 1 round/level. If the spell is cast upon a target that is not freestanding the surrounding stone dissipates the effect and no damage occurs.</p><p><i>Sympathetic vibration</i> cannot affect creatures (including constructs). Since a structure is an unattended object, it gets no saving throw to resist the effect.</p><p><i>Focus:</i> A tuning fork.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (640,'Sympathy','sympathy','Enchantment','Compulsion','Mind-Affecting',NULL,'Druid 9, Sorcerer/Wizard 8','V, S, M','1 hour','Close (25 ft. + 5 ft./2 levels)','One location (up to a 10-ft. cube/level) or one object',NULL,NULL,'2 hours/level (D)','Will negates; see text','Yes','Object or location attracts certain creatures.',NULL,'1,500 gp worth of crushed pearls and a drop of honey.',NULL,NULL,'\n      <p>You cause an object or location to emanate magical vibrations that attract either a specific kind of intelligent creature or creatures of a particular alignment, as defined by you. The particular kind of creature to be affected must be named specifically. A creature subtype is not specific enough. Likewise, the specific alignment must be named.</p>\n      <p>Creatures of the specified kind or alignment feel elated and pleased to be in the area or desire to touch or to possess the object. The compulsion to stay in the area or touch the object is overpowering. If the save is successful, the creature is released from the enchantment, but a subsequent save must be made 1d6x10 minutes later. If this save fails, the affected creature attempts to return to the area or object.</p>\n      <p><i>Sympathy</i> counters and dispels <i>antipathy</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sympathy\" level=\"5\"><p><h5>Sympathy</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 9, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 hour<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One location (up to a 10-ft. cube/level) or one object<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You cause an object or location to emanate magical vibrations that attract either a specific kind of intelligent creature or creatures of a particular alignment, as defined by you. The particular kind of creature to be affected must be named specifically. A creature subtype is not specific enough. Likewise, the specific alignment must be named.</p><p>Creatures of the specified kind or alignment feel elated and pleased to be in the area or desire to touch or to possess the object. The compulsion to stay in the area or touch the object is overpowering. If the save is successful, the creature is released from the enchantment, but a subsequent save must be made 1d6x10 minutes later. If this save fails, the affected creature attempts to return to the area or object.</p><p><i>Sympathy</i> counters and dispels <i>antipathy</i>.</p><p><i>Material Component:</i> 1,500 gp worth of crushed pearls and a drop of honey.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (641,'Telekinesis','telekinesis','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 5','V, S','1 standard action','Long (400 ft. + 40 ft./level)','See text',NULL,NULL,'Concentration (up to 1 round/level) or instantaneous; see text','Will negates (object) or None; see text','Yes (object); see text','Moves object, attacks creature, or hurls object or creature.',NULL,NULL,NULL,NULL,'\n      <p>You move objects or creatures by concentrating on them. Depending on the version selected, the spell can provide a gentle, sustained force, perform a variety of combat maneuvers, or exert a single short, violent thrust.</p>\n      <p><i>Sustained Force:</i> A sustained force moves an object weighing no more than 25 pounds per caster level (maximum 375 pounds at 15th level) up to 20 feet per round. A creature can negate the effect on an object it possesses with a successful Will save or with spell resistance.</p>\n      <p>This version of the spell can last 1 round per caster level, but it ends if you cease concentration. The weight can be moved vertically, horizontally, or in both directions. An object cannot be moved beyond your range. The spell ends if the object is forced beyond the range. If you cease concentration for any reason, the object falls or stops.</p>\n      <p>An object can be telekinetically manipulated as if with one hand. For example, a lever or rope can be pulled, a key can be turned, an object rotated, and so on, if the force required is within the weight limitation. You might even be able to untie simple knots, though delicate activities such as these require Intelligence checks.</p>\n      <p><i>Combat Maneuver:</i> Alternatively, once per round, you can use <i>telekinesis</i> to perform a bull rush, disarm, grapple (including pin), or trip. Resolve these attempts as normal, except that they don\'t provoke attacks of opportunity, you use your caster level in place of your base attack bonus (for disarm and grapple), you use your Intelligence modifier (if a wizard) or Charisma modifier (if a sorcerer) in place of your Strength or Dexterity modifier, and a failed attempt doesn\'t allow a reactive attempt by the target (such as for disarm or trip). No save is allowed against these attempts, but spell resistance applies normally. This version of the spell can last 1 round per caster level, but it ends if you cease concentration.</p>\n      <p><i>Violent Thrust:</i> Alternatively, the spell energy can be spent in a single round. You can hurl one object or creature per caster level (maximum 15) that are within range and all within 10 feet of each other toward any target within 10 feet per level of all the objects. You can hurl up to a total weight of 25 pounds per caster level (maximum 375 pounds at 15th level).</p>\n      <p>You must succeed on attack rolls (one per creature or object thrown) to hit the target with the items, using your base attack bonus + your Intelligence modifier (if a wizard) or Charisma modifier (if a sorcerer). Weapons cause standard damage (with no Strength bonus; note that arrows or bolts deal damage as daggers of their size when used in this manner). Other objects cause damage ranging from 1 point per 25 pounds (for less dangerous objects) to 1d6 points of damage per 25 pounds (for hard, dense objects).</p>\n      <p>Creatures who fall within the weight capacity of the spell can be hurled, but they are allowed Will saves (and spell resistance) to negate the effect, as are those whose held possessions are targeted by the spell. If a telekinesed creature is hurled against a solid surface, it takes damage as if it had fallen 10 feet (1d6 points).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Telekinesis\" level=\"5\"><p><h5>Telekinesis</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target or Targets:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration (up to 1 round/level) or instantaneous; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object) or None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object); see text<br/></td></tr></table><p>You move objects or creatures by concentrating on them. Depending on the version selected, the spell can provide a gentle, sustained force, perform a variety of combat maneuvers, or exert a single short, violent thrust.</p><p><i>Sustained Force:</i> A sustained force moves an object weighing no more than 25 pounds per caster level (maximum 375 pounds at 15th level) up to 20 feet per round. A creature can negate the effect on an object it possesses with a successful Will save or with spell resistance.</p><p>This version of the spell can last 1 round per caster level, but it ends if you cease concentration. The weight can be moved vertically, horizontally, or in both directions. An object cannot be moved beyond your range. The spell ends if the object is forced beyond the range. If you cease concentration for any reason, the object falls or stops.</p><p>An object can be telekinetically manipulated as if with one hand. For example, a lever or rope can be pulled, a key can be turned, an object rotated, and so on, if the force required is within the weight limitation. You might even be able to untie simple knots, though delicate activities such as these require Intelligence checks.</p><p><i>Combat Maneuver:</i> Alternatively, once per round, you can use <i>telekinesis</i> to perform a bull rush, disarm, grapple (including pin), or trip. Resolve these attempts as normal, except that they don\'t provoke attacks of opportunity, you use your caster level in place of your base attack bonus (for disarm and grapple), you use your Intelligence modifier (if a wizard) or Charisma modifier (if a sorcerer) in place of your Strength or Dexterity modifier, and a failed attempt doesn\'t allow a reactive attempt by the target (such as for disarm or trip). No save is allowed against these attempts, but spell resistance applies normally. This version of the spell can last 1 round per caster level, but it ends if you cease concentration.</p><p><i>Violent Thrust:</i> Alternatively, the spell energy can be spent in a single round. You can hurl one object or creature per caster level (maximum 15) that are within range and all within 10 feet of each other toward any target within 10 feet per level of all the objects. You can hurl up to a total weight of 25 pounds per caster level (maximum 375 pounds at 15th level).</p><p>You must succeed on attack rolls (one per creature or object thrown) to hit the target with the items, using your base attack bonus + your Intelligence modifier (if a wizard) or Charisma modifier (if a sorcerer). Weapons cause standard damage (with no Strength bonus; note that arrows or bolts deal damage as daggers of their size when used in this manner). Other objects cause damage ranging from 1 point per 25 pounds (for less dangerous objects) to 1d6 points of damage per 25 pounds (for hard, dense objects).</p><p>Creatures who fall within the weight capacity of the spell can be hurled, but they are allowed Will saves (and spell resistance) to negate the effect, as are those whose held possessions are targeted by the spell. If a telekinesed creature is hurled against a solid surface, it takes damage as if it had fallen 10 feet (1d6 points).</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (642,'Telekinetic Sphere','telekinetic sphere','Evocation',NULL,'Force',NULL,'Sorcerer/Wizard 8','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'1-ft. -diameter/level sphere, centered around creatures or objects','1 min./level (D)','Reflex negates (object)','Yes (object)','As resilient sphere, but you move sphere telekinetically.',NULL,'A hemispherical piece of clear crystal, a matching hemispherical piece of gum arabic, and a pair of small bar magnets.',NULL,NULL,'\n      <p>This spell functions like <i>resilient sphere</i>,  with the addition that the creatures or objects inside the globe are nearly weightless. Anything contained within an <i>telekinetic sphere</i> weighs only one-sixteenth of its normal weight. You can telekinetically lift anything in the sphere that normally weighs 5,000 pounds or less. The telekinetic control extends from you out to medium range (100 feet + 10 feet per caster level) after the sphere has succeeded in encapsulating its contents.</p>\n      <p>You can move objects or creatures in the sphere that weigh a total of 5,000 pounds or less by concentrating on the sphere. You can begin moving a sphere in the round after casting the spell. If you concentrate on doing so (a standard action), you can move the sphere as much as 30 feet in a round. If you cease concentrating, the sphere does not move in that round (if on a level surface) or descends at its falling rate (if aloft) until it reaches a level surface, or the spell\'s duration expires, or you begin concentrating again. If you cease concentrating (voluntarily or due to failing a Concentration check), you can resume concentrating on your next turn or any later turn during the spell\'s duration.</p>\n      <p>The sphere falls at a rate of only 60 feet per round, which is not fast enough to cause damage to the contents of the sphere.</p>\n      <p>You can move the sphere telekinetically even if you are in it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Telekinetic Sphere\" level=\"5\"><p><h5>Telekinetic Sphere</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>1-ft. -diameter/level sphere, centered around creatures or objects<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>This spell functions like <i>resilient sphere</i>,  with the addition that the creatures or objects inside the globe are nearly weightless. Anything contained within an <i>telekinetic sphere</i> weighs only one-sixteenth of its normal weight. You can telekinetically lift anything in the sphere that normally weighs 5,000 pounds or less. The telekinetic control extends from you out to medium range (100 feet + 10 feet per caster level) after the sphere has succeeded in encapsulating its contents.</p><p>You can move objects or creatures in the sphere that weigh a total of 5,000 pounds or less by concentrating on the sphere. You can begin moving a sphere in the round after casting the spell. If you concentrate on doing so (a standard action), you can move the sphere as much as 30 feet in a round. If you cease concentrating, the sphere does not move in that round (if on a level surface) or descends at its falling rate (if aloft) until it reaches a level surface, or the spell\'s duration expires, or you begin concentrating again. If you cease concentrating (voluntarily or due to failing a Concentration check), you can resume concentrating on your next turn or any later turn during the spell\'s duration.</p><p>The sphere falls at a rate of only 60 feet per round, which is not fast enough to cause damage to the contents of the sphere.</p><p>You can move the sphere telekinetically even if you are in it.</p><p><i>Material Component:</i> A hemispherical piece of clear crystal, a matching hemispherical piece of gum arabic, and a pair of small bar magnets.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (643,'Telepathic Bond','telepathic bond','Divination',NULL,NULL,NULL,'Sorcerer/Wizard 5','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','You plus one willing creature per three levels, no two of which can be more than 30 ft. apart',NULL,NULL,'10 min./level (D)','None','No','Link lets allies communicate.',NULL,'Pieces of eggshell from two different kinds of creatures.',NULL,NULL,'\n      <p>You forge a telepathic bond among yourself and a number of willing creatures, each of which must have an Intelligence score of 3 or higher. Each creature included in the link is linked to all the others. The creatures can communicate telepathically through the bond regardless of language. No special power or influence is established as a result of the bond. Once the bond is formed, it works over any distance (although not from one plane to another).</p>\n      <p>If desired, you may leave yourself out of the telepathic bond forged. This decision must be made at the time of casting.</p>\n      <p><i>Telepathic bond</i> can be made permanent with a <i>permanency</i> spell, though it only bonds two creatures per casting of <i>permanency</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Telepathic Bond\" level=\"5\"><p><h5>Telepathic Bond</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>You plus one willing creature per three levels, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You forge a telepathic bond among yourself and a number of willing creatures, each of which must have an Intelligence score of 3 or higher. Each creature included in the link is linked to all the others. The creatures can communicate telepathically through the bond regardless of language. No special power or influence is established as a result of the bond. Once the bond is formed, it works over any distance (although not from one plane to another).</p><p>If desired, you may leave yourself out of the telepathic bond forged. This decision must be made at the time of casting.</p><p><i>Telepathic bond</i> can be made permanent with a <i>permanency</i> spell, though it only bonds two creatures per casting of <i>permanency</i>.</p><p><i>Material Component:</i> Pieces of eggshell from two different kinds of creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (644,'Teleport','teleport','Conjuration','Teleportation',NULL,NULL,'Sorcerer/Wizard 5, Travel 5','V','1 standard action','Personal and touch','You and touched objects or other touched willing creatures',NULL,NULL,'Instantaneous','None and Will negates (object)','No and Yes (object)','Instantly transports you as far as 100 miles/level.',NULL,NULL,NULL,NULL,'\n      <p>This spell instantly transports you to a designated destination, which may be as distant as 100 miles per caster level. Interplanar travel is not possible. You can bring along objects as long as their weight doesn\'t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent (see below) per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. As with all spells where the range is personal and the target is you, you need not make a saving throw, nor is spell resistance applicable to you. Only objects held or in use (attended) by another person receive saving throws and spell resistance.</p>\n      <p>You must have some clear idea of the location and layout of the destination. The clearer your mental image, the more likely the teleportation works. Areas of strong physical or magical energy may make teleportation more hazardous or even impossible.</p>\n      <p>To see how well the teleportation works, roll d% and consult the Teleport table. Refer to the following information for definitions of the terms on the table.</p>\n      <p><i>Familiarity:</i> \'Very familiar\' is a place where you have been very often and where you feel at home. \'Studied carefully\' is a place you know well, either because you can currently see it, you\'ve been there often, or you have used other means (such as <i>scrying</i>) to study the place for at least one hour. \'Seen casually\' is a place that you have seen more than once but with which you are not very familiar. \'Viewed once\' is a place that you have seen once, possibly using magic.</p>\n      <p>\'False destination\' is a place that does not truly exist or if you are teleporting to an otherwise familiar location that no longer exists as such or has been so completely altered as to no longer be familiar to you. When traveling to a false destination, roll 1d20+80 to obtain results on the table, rather than rolling d%, since there is no real destination for you to hope to arrive at or even be off target from.</p>\n      <p><i>On Target:</i> You appear where you want to be.</p>\n      <p><i>Off Target:</i> You appear safely a random distance away from the destination in a random direction. Distance off target is 1d10x1d10% of the distance that was to be traveled. The direction off target is determined randomly</p>\n      <p><i>Similar Area:</i> You wind up in an area that\'s visually or thematically similar to the target area.</p>\n      <p>Generally, you appear in the closest similar place within range. If no such area exists within the spell\'s range, the spell simply fails instead.</p>\n      <p><i>Mishap:</i> You and anyone else teleporting with you have gotten \'scrambled.\' You each take 1d10 points of damage, and you reroll on the chart to see where you wind up. For these rerolls, roll 1d20+80. Each time \'Mishap\' comes up, the characters take more damage and must reroll.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Familiarity</b><br/></td>\n<td><b>On Target</b><br/></td>\n<td><b>Off Target</b><br/></td>\n<td><b>Similar Area</b><br/></td>\n<td><b>Mishap</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Very familiar<br/></td>\n<td>01-97<br/></td>\n<td>98-99<br/></td>\n<td>100<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Studied carefully<br/></td>\n<td>01-94<br/></td>\n<td>95-97<br/></td>\n<td>98-99<br/></td>\n<td>100<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Seen casually<br/></td>\n<td>01-88<br/></td>\n<td>89-94<br/></td>\n<td>95-98<br/></td>\n<td>99-100<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Viewed once<br/></td>\n<td>01-76<br/></td>\n<td>77-88<br/></td>\n<td>89-96<br/></td>\n<td>97-100<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>False destination (1d20+80)<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>81-92<br/></td>\n<td>93-100<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Teleport\" level=\"5\"><p><h5>Teleport</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5, Travel 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal and touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You and touched objects or other touched willing creatures<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None and Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No and Yes (object)<br/></td></tr></table><p>This spell instantly transports you to a designated destination, which may be as distant as 100 miles per caster level. Interplanar travel is not possible. You can bring along objects as long as their weight doesn\'t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent (see below) per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. As with all spells where the range is personal and the target is you, you need not make a saving throw, nor is spell resistance applicable to you. Only objects held or in use (attended) by another person receive saving throws and spell resistance.</p><p>You must have some clear idea of the location and layout of the destination. The clearer your mental image, the more likely the teleportation works. Areas of strong physical or magical energy may make teleportation more hazardous or even impossible.</p><p>To see how well the teleportation works, roll d% and consult the Teleport table. Refer to the following information for definitions of the terms on the table.</p><p><i>Familiarity:</i> \'Very familiar\' is a place where you have been very often and where you feel at home. \'Studied carefully\' is a place you know well, either because you can currently see it, you\'ve been there often, or you have used other means (such as <i>scrying</i>) to study the place for at least one hour. \'Seen casually\' is a place that you have seen more than once but with which you are not very familiar. \'Viewed once\' is a place that you have seen once, possibly using magic.</p><p>\'False destination\' is a place that does not truly exist or if you are teleporting to an otherwise familiar location that no longer exists as such or has been so completely altered as to no longer be familiar to you. When traveling to a false destination, roll 1d20+80 to obtain results on the table, rather than rolling d%, since there is no real destination for you to hope to arrive at or even be off target from.</p><p><i>On Target:</i> You appear where you want to be.</p><p><i>Off Target:</i> You appear safely a random distance away from the destination in a random direction. Distance off target is 1d10x1d10% of the distance that was to be traveled. The direction off target is determined randomly</p><p><i>Similar Area:</i> You wind up in an area that\'s visually or thematically similar to the target area.</p><p>Generally, you appear in the closest similar place within range. If no such area exists within the spell\'s range, the spell simply fails instead.</p><p><i>Mishap:</i> You and anyone else teleporting with you have gotten \'scrambled.\' You each take 1d10 points of damage, and you reroll on the chart to see where you wind up. For these rerolls, roll 1d20+80. Each time \'Mishap\' comes up, the characters take more damage and must reroll.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Familiarity</b><br/></td>\n<td><b>On Target</b><br/></td>\n<td><b>Off Target</b><br/></td>\n<td><b>Similar Area</b><br/></td>\n<td><b>Mishap</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Very familiar<br/></td>\n<td>01-97<br/></td>\n<td>98-99<br/></td>\n<td>100<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Studied carefully<br/></td>\n<td>01-94<br/></td>\n<td>95-97<br/></td>\n<td>98-99<br/></td>\n<td>100<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Seen casually<br/></td>\n<td>01-88<br/></td>\n<td>89-94<br/></td>\n<td>95-98<br/></td>\n<td>99-100<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Viewed once<br/></td>\n<td>01-76<br/></td>\n<td>77-88<br/></td>\n<td>89-96<br/></td>\n<td>97-100<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>False destination (1d20+80)<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>81-92<br/></td>\n<td>93-100<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (645,'Teleport Object','teleport object','Conjuration','Teleportation',NULL,NULL,'Sorcerer/Wizard 7','V','1 standard action','Touch','One touched object of up to 50 lb./level and 3 cu. ft./level',NULL,NULL,'Instantaneous','Will negates (object)','Yes (object)','As teleport, but affects a touched object.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>teleport</i>,  except that it teleports an object, not you. Creatures and magical forces cannot be teleported.</p>\n      <p>If desired, the target object can be sent to a distant location on the Ethereal Plane. In this case, the point from which the object was teleported remains faintly magical until the item is retrieved. A successful targeted <i>dispel magic</i> spell cast on that point brings the vanished item back from the Ethereal Plane.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Teleport Object\" level=\"5\"><p><h5>Teleport Object</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One touched object of up to 50 lb./level and 3 cu. ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>This spell functions like <i>teleport</i>,  except that it teleports an object, not you. Creatures and magical forces cannot be teleported.</p><p>If desired, the target object can be sent to a distant location on the Ethereal Plane. In this case, the point from which the object was teleported remains faintly magical until the item is retrieved. A successful targeted <i>dispel magic</i> spell cast on that point brings the vanished item back from the Ethereal Plane.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (646,'Teleport, Greater','greater teleport','Conjuration','Teleportation',NULL,NULL,'Sorcerer/Wizard 7, Travel 7','V','1 standard action','Personal and touch','You and touched objects or other touched willing creatures',NULL,NULL,'Instantaneous','None and Will negates (object)','No and Yes (object)','As teleport, but no range limit and no off-target arrival.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>teleport</i>,  except that there is no range limit and there is no chance you arrive off target. In addition, you need not have seen the destination, but in that case you must have at least a reliable description of the place to which you are teleporting. If you attempt to teleport with insufficient information (or with misleading information), you disappear and simply reappear in your original location. Interplanar travel is not possible.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Teleport, Greater\" level=\"5\"><p><h5>Teleport, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7, Travel 7<br/></td></tr></table><p>This spell functions like <i>teleport</i>,  except that there is no range limit and there is no chance you arrive off target. In addition, you need not have seen the destination, but in that case you must have at least a reliable description of the place to which you are teleporting. If you attempt to teleport with insufficient information (or with misleading information), you disappear and simply reappear in your original location. Interplanar travel is not possible.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (647,'Teleportation Circle','teleportation circle','Conjuration','Teleportation',NULL,NULL,'Sorcerer/Wizard 9','V, M','10 minutes','0 ft.',NULL,NULL,'5-ft. -radius circle that teleports those who activate it','10 min./level (D)','None','Yes','Circle teleports any creature inside to designated spot.',NULL,'Amber dust to cover the area of the circle (cost 1,000 gp).',NULL,NULL,'\n      <p>You create a circle on the floor or other horizontal surface that teleports, as <i>greater teleport</i>,  any creature who stands on it to a designated spot. Once you designate the destination for the circle, you can\'t change it. The spell fails if you attempt to set the circle to teleport creatures into a solid object, to a place with which you are not familiar and have no clear description, or to another plane.</p>\n      <p>The circle itself is subtle and nearly impossible to notice. If you intend to keep creatures from activating it accidentally, you need to mark the circle in some way.</p>\n      <p><i>teleportation circle</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>teleportation circle</i> that is disabled becomes inactive for 10 minutes, then can be triggered again as normal.</p>\n      <p><i>Note:</i> Magic traps such as <i>teleportation circle</i> are hard to detect and disable. A rogue (only) can use the Search skill to find the circle and Disable Device to thwart it. The DC in each case is 25 + spell level, or 34 in the case of <i>teleportation circle</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Teleportation Circle\" level=\"5\"><p><h5>Teleportation Circle</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>5-ft. -radius circle that teleports those who activate it<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You create a circle on the floor or other horizontal surface that teleports, as <i>greater teleport</i>,  any creature who stands on it to a designated spot. Once you designate the destination for the circle, you can\'t change it. The spell fails if you attempt to set the circle to teleport creatures into a solid object, to a place with which you are not familiar and have no clear description, or to another plane.</p><p>The circle itself is subtle and nearly impossible to notice. If you intend to keep creatures from activating it accidentally, you need to mark the circle in some way.</p><p><i>teleportation circle</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>teleportation circle</i> that is disabled becomes inactive for 10 minutes, then can be triggered again as normal.</p><p><i>Note:</i> Magic traps such as <i>teleportation circle</i> are hard to detect and disable. A rogue (only) can use the Search skill to find the circle and Disable Device to thwart it. The DC in each case is 25 + spell level, or 34 in the case of <i>teleportation circle</i>.</p><p><i>Material Component:</i> Amber dust to cover the area of the circle (cost 1,000 gp).</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (648,'Temporal Stasis','temporal stasis','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 8','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'Permanent','Fortitude negates','Yes','Puts subject into suspended animation.',NULL,'A powder composed of diamond, emerald, ruby, and sapphire dust with a total value of at least 5,000 gp.',NULL,NULL,'\n      <p>You must succeed on a melee touch attack. You place the subject into a state of suspended animation. For the creature, time ceases to flow and its condition becomes fixed. The creature does not grow older. Its body functions virtually cease, and no force or effect can harm it. This state persists until the magic is removed (such as by a successful <i>dispel magic</i> spell or a <i>freedom</i> spell).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Temporal Stasis\" level=\"5\"><p><h5>Temporal Stasis</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You must succeed on a melee touch attack. You place the subject into a state of suspended animation. For the creature, time ceases to flow and its condition becomes fixed. The creature does not grow older. Its body functions virtually cease, and no force or effect can harm it. This state persists until the magic is removed (such as by a successful <i>dispel magic</i> spell or a <i>freedom</i> spell).</p><p><i>Material Component:</i> A powder composed of diamond, emerald, ruby, and sapphire dust with a total value of at least 5,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (649,'Time Stop','time stop','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 9, Trickery 9','V','1 standard action','Personal','You',NULL,NULL,'1d4+1 rounds (apparent time); see text',NULL,NULL,'You act freely for 1d4+1 rounds.',NULL,NULL,NULL,NULL,'\n      <p>This spell seems to make time cease to flow for everyone but you. In fact, you speed up so greatly that all other creatures seem frozen, though they are actually still moving at their normal speeds. You are free to act for 1d4+1 rounds of apparent time. Normal and magical fire, cold, gas, and the like can still harm you. While the <i>time stop</i> is in effect, other creatures are invulnerable to your attacks and spells; you cannot target such creatures with any attack or spell. A spell that affects an area and has a duration longer than the remaining duration of the <i>time stop</i> have their normal effects on other creatures once the <i>time stop</i> ends. Most spellcasters use the additional time to improve their defenses, summon allies, or flee from combat.</p>\n      <p>You cannot move or harm items held, carried, or worn by a creature stuck in normal time, but you can affect any item that is not in another creature\'s possession.</p>\n      <p>You are undetectable while <i>time stop</i> lasts. You cannot enter an area protected by an <i>antimagic field</i> while under the effect of <i>time stop</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Time Stop\" level=\"5\"><p><h5>Time Stop</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9, Trickery 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1d4+1 rounds (apparent time); see text<br/></td></tr></table><p>This spell seems to make time cease to flow for everyone but you. In fact, you speed up so greatly that all other creatures seem frozen, though they are actually still moving at their normal speeds. You are free to act for 1d4+1 rounds of apparent time. Normal and magical fire, cold, gas, and the like can still harm you. While the <i>time stop</i> is in effect, other creatures are invulnerable to your attacks and spells; you cannot target such creatures with any attack or spell. A spell that affects an area and has a duration longer than the remaining duration of the <i>time stop</i> have their normal effects on other creatures once the <i>time stop</i> ends. Most spellcasters use the additional time to improve their defenses, summon allies, or flee from combat.</p><p>You cannot move or harm items held, carried, or worn by a creature stuck in normal time, but you can affect any item that is not in another creature\'s possession.</p><p>You are undetectable while <i>time stop</i> lasts. You cannot enter an area protected by an <i>antimagic field</i> while under the effect of <i>time stop</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (650,'Tiny Hut','tiny hut','Evocation',NULL,'Force',NULL,'Bard 3, Sorcerer/Wizard 3','V, S, M','1 standard action','20 ft.',NULL,NULL,'20-ft. -radius sphere centered on your location','2 hours/level (D)','None','No','Creates shelter for ten creatures.',NULL,'A small crystal bead that shatters when the spell duration expires or the hut is dispelled.',NULL,NULL,'\n      <p>You create an unmoving, opaque sphere of force of any color you desire around yourself. Half the sphere projects above the ground, and the lower hemisphere passes through the ground. As many as nine other Medium creatures can fit into the field with you; they can freely pass into and out of the hut without harming it. However, if you remove yourself from the hut, the spell ends.</p>\n      <p>The temperature inside the hut is 70&#xB0; F if the exterior temperature is between 0&#xB0; and 100&#xB0; F. An exterior temperature below 0&#xB0; or above 100&#xB0; lowers or raises the interior temperature on a 1-degree-for-1 basis. The hut also provides protection against the elements, such as rain, dust, and sandstorms. The hut withstands any wind of less than hurricane force, but a hurricane (75+ mph wind speed) or greater force destroys it.</p>\n      <p>The interior of the hut is a hemisphere. You can illuminate it dimly upon command or extinguish the light as desired. Although the force field is opaque from the outside, it is transparent from within. Missiles, weapons, and most spell effects can pass through the hut without affecting it, although the occupants cannot be seen from outside the hut (they have total concealment).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Tiny Hut\" level=\"5\"><p><h5>Tiny Hut</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>20 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>20-ft. -radius sphere centered on your location<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You create an unmoving, opaque sphere of force of any color you desire around yourself. Half the sphere projects above the ground, and the lower hemisphere passes through the ground. As many as nine other Medium creatures can fit into the field with you; they can freely pass into and out of the hut without harming it. However, if you remove yourself from the hut, the spell ends.</p><p>The temperature inside the hut is 70&#xB0; F if the exterior temperature is between 0&#xB0; and 100&#xB0; F. An exterior temperature below 0&#xB0; or above 100&#xB0; lowers or raises the interior temperature on a 1-degree-for-1 basis. The hut also provides protection against the elements, such as rain, dust, and sandstorms. The hut withstands any wind of less than hurricane force, but a hurricane (75+ mph wind speed) or greater force destroys it.</p><p>The interior of the hut is a hemisphere. You can illuminate it dimly upon command or extinguish the light as desired. Although the force field is opaque from the outside, it is transparent from within. Missiles, weapons, and most spell effects can pass through the hut without affecting it, although the occupants cannot be seen from outside the hut (they have total concealment).</p><p><i>Material Component:</i> A small crystal bead that shatters when the spell duration expires or the <i>hut</i> is dispelled.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (651,'Tongues','tongues','Divination',NULL,NULL,NULL,'Bard 2, Cleric 4, Sorcerer/Wizard 3','V, M/DF','1 standard action','Touch','Creature touched',NULL,NULL,'10 min./level','Will negates (harmless)','No','Speak any language.',NULL,NULL,'A small clay model of a ziggurat, which shatters when the verbal component is pronounced.',NULL,'\n      <p>This spell grants the creature touched the ability to speak and understand the language of any intelligent creature, whether it is a racial tongue or a regional dialect. The subject can speak only one language at a time, although it may be able to understand several languages. <i>Tongues</i> does not enable the subject to speak with creatures who don\'t speak. The subject can make itself understood as far as its voice carries. This spell does not predispose any creature addressed toward the subject in any way.</p>\n      <p><i>Tongues</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Tongues\" level=\"5\"><p><h5>Tongues</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 4, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell grants the creature touched the ability to speak and understand the language of any intelligent creature, whether it is a racial tongue or a regional dialect. The subject can speak only one language at a time, although it may be able to understand several languages. <i>Tongues</i> does not enable the subject to speak with creatures who don\'t speak. The subject can make itself understood as far as its voice carries. This spell does not predispose any creature addressed toward the subject in any way.</p><p><i>Tongues</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Arcane Material Component:</i> A small clay model of a ziggurat, which shatters when the verbal component is pronounced.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (652,'Touch of Fatigue','touch of fatigue','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 0','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'1 round/level','Fortitude negates','Yes','Touch attack fatigues target.',NULL,'A drop of sweat.',NULL,NULL,'\n      <p>You channel negative energy through your touch, fatiguing the target. You must succeed on a touch attack to strike a target.</p>\n      <p>The subject is immediately fatigued for the spell\'s duration.</p>\n      <p>This spell has no effect on a creature that is already fatigued. Unlike with normal fatigue, the effect ends as soon as the spell\'s duration expires.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Touch of Fatigue\" level=\"5\"><p><h5>Touch of Fatigue</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You channel negative energy through your touch, fatiguing the target. You must succeed on a touch attack to strike a target.</p><p>The subject is immediately fatigued for the spell\'s duration.</p><p>This spell has no effect on a creature that is already fatigued. Unlike with normal fatigue, the effect ends as soon as the spell\'s duration expires.</p><p><i>Material Component:</i> A drop of sweat.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (653,'Touch of Idiocy','touch of idiocy','Enchantment','Compulsion','Mind-Affecting',NULL,'Sorcerer/Wizard 2','V, S','1 standard action','Touch','Living creature touched',NULL,NULL,'10 min./level','No','Yes','Subject takes 1d6 points of Int, Wis, and Cha damage.',NULL,NULL,NULL,NULL,'\n      <p>With a touch, you reduce the target\'s mental faculties. Your successful melee touch attack applies a 1d6 penalty to the target\'s Intelligence, Wisdom, and Charisma scores. This penalty can\'t reduce any of these scores below 1.</p>\n      <p>This spell\'s effect may make it impossible for the target to cast some or all of its spells, if the requisite ability score drops below the minimum required to cast spells of that level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Touch of Idiocy\" level=\"5\"><p><h5>Touch of Idiocy</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>With a touch, you reduce the target\'s mental faculties. Your successful melee touch attack applies a 1d6 penalty to the target\'s Intelligence, Wisdom, and Charisma scores. This penalty can\'t reduce any of these scores below 1.</p><p>This spell\'s effect may make it impossible for the target to cast some or all of its spells, if the requisite ability score drops below the minimum required to cast spells of that level.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (654,'Transformation','transformation','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 6','V, S, M','1 standard action','Personal','You',NULL,NULL,'1 round/level',NULL,NULL,'You gain combat bonuses.',NULL,'A potion of bull\'s strength, which you drink (and whose effects are subsumed by the spell effects).',NULL,NULL,'\n      <p>You become a virtual fighting machine- stronger, tougher, faster, and more skilled in combat. Your mind-set changes so that you relish combat and you can\'t cast spells, even from magic items.</p>\n      <p>You gain a +4 enhancement bonus to Strength, Dexterity, and Constitution, a +4 natural armor bonus to AC, a +5 competence bonus on Fortitude saves, and proficiency with all simple and martial weapons. Your base attack bonus equals your character level (which may give you multiple attacks).</p>\n      <p>You lose your spellcasting ability, including your ability to use spell activation or spell completion magic items, just as if the spells were no longer on your class list.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Transformation\" level=\"5\"><p><h5>Transformation</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr></table><p>You become a virtual fighting machine- stronger, tougher, faster, and more skilled in combat. Your mind-set changes so that you relish combat and you can\'t cast spells, even from magic items.</p><p>You gain a +4 enhancement bonus to Strength, Dexterity, and Constitution, a +4 natural armor bonus to AC, a +5 competence bonus on Fortitude saves, and proficiency with all simple and martial weapons. Your base attack bonus equals your character level (which may give you multiple attacks).</p><p>You lose your spellcasting ability, including your ability to use spell activation or spell completion magic items, just as if the spells were no longer on your class list.</p><p><i>Material Component:</i> A <i>potion of bull\'s strength</i>, which you drink (and whose effects are subsumed by the spell effects).</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (655,'Transmute Metal to Wood','transmute metal to wood','Transmutation',NULL,NULL,NULL,'Druid 7','V, S, DF','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'All metal objects within a 40-ft. -radius burst',NULL,'Instantaneous','None','Yes (object; see text)','Metal within 40 ft. becomes wood.',NULL,NULL,NULL,NULL,'\n      <p>This spell enables you to change all metal objects within its area to wood. Weapons, armor, and other metal objects carried by creatures are affected as well. A magic object made of metal effectively has spell resistance equal to 20 + its caster level against this spell. Artifacts cannot be transmuted. Weapons converted from metal to wood take a -2 penalty on attack and damage rolls. The armor bonus of any armor converted from metal to wood is reduced by 2. Weapons changed by this spell splinter and break on any natural attack roll of 1 or 2, and armor changed by this spell loses an additional point of armor bonus every time it is struck with a natural attack roll of 19 or 20.</p>\n      <p>Only <i>limited wish</i>,  <i>miracle</i>,  <i>wish</i>,  or similar magic can restore a transmuted object to its metallic state.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Transmute Metal to Wood\" level=\"5\"><p><h5>Transmute Metal to Wood</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>All metal objects within a 40-ft. -radius burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object; see text)<br/></td></tr></table><p>This spell enables you to change all metal objects within its area to wood. Weapons, armor, and other metal objects carried by creatures are affected as well. A magic object made of metal effectively has spell resistance equal to 20 + its caster level against this spell. Artifacts cannot be transmuted. Weapons converted from metal to wood take a -2 penalty on attack and damage rolls. The armor bonus of any armor converted from metal to wood is reduced by 2. Weapons changed by this spell splinter and break on any natural attack roll of 1 or 2, and armor changed by this spell loses an additional point of armor bonus every time it is struck with a natural attack roll of 19 or 20.</p><p>Only <i>limited wish</i>,  <i>miracle</i>,  <i>wish</i>,  or similar magic can restore a transmuted object to its metallic state.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (656,'Transmute Mud to Rock','transmute mud to rock','Transmutation',NULL,'Earth',NULL,'Druid 5, Sorcerer/Wizard 5','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Up to two 10-ft. cubes/level (S)',NULL,'Permanent','See text','No','Transforms two 10-ft. cubes per level.',NULL,NULL,'Sand, lime, and water.',NULL,'\n      <p>This spell transforms normal mud or quicksand of any depth into soft stone (sandstone or a similar mineral) permanently.</p>\n      <p>Any creature in the mud is allowed a Reflex save to escape before the area is hardened to stone.</p>\n      <p><i>Transmute mud to rock</i> counters and dispels <i>transmute rock to mud</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Transmute Mud to Rock\" level=\"5\"><p><h5>Transmute Mud to Rock</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Up to two 10-ft. cubes/level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell transforms normal mud or quicksand of any depth into soft stone (sandstone or a similar mineral) permanently.</p><p>Any creature in the mud is allowed a Reflex save to escape before the area is hardened to stone.</p><p><i>Transmute mud to rock</i> counters and dispels <i>transmute rock to mud</i>.</p><p><i>Arcane Material Component:</i> Sand, lime, and water.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (657,'Transmute Rock to Mud','transmute rock to mud','Transmutation',NULL,'Earth',NULL,'Druid 5, Sorcerer/Wizard 5','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Up to two 10-ft. cubes/level (S)',NULL,'Permanent; see text','See text','No','Transforms two 10-ft. cubes per level.',NULL,NULL,'Clay and water.',NULL,'\n      <p>This spell turns natural, uncut or unworked rock of any sort into an equal volume of mud. Magical stone is not affected by the spell. The depth of the mud created cannot exceed 10 feet. A creature unable to levitate, fly, or otherwise free itself from the mud sinks until hip- or chest-deep, reducing its speed to 5 feet and causing a -2 penalty on attack rolls and AC. Brush thrown atop the mud can support creatures able to climb on top of it. Creatures large enough to walk on the bottom can wade through the area at a speed of 5 feet.</p>\n      <p>If <i>transmute rock to mud</i> is cast upon the ceiling of a cavern or tunnel, the mud falls to the floor and spreads out in a pool at a depth of 5 feet. The falling mud and the ensuing cave-in deal 8d6 points of bludgeoning damage to anyone caught directly beneath the area, or half damage to those who succeed on Reflex saves.</p>\n      <p>Castles and large stone buildings are generally immune to the effect of the spell, since <i>transmute rock to mud</i> can\'t affect worked stone and doesn\'t reach deep enough to undermine such buildings\' foundations. However, small buildings or structures often rest upon foundations shallow enough to be damaged or even partially toppled by this spell.</p>\n      <p>The mud remains until a successful <i>dispel magic</i> or <i>Transmute mud to rock</i> spell restores its substance-but not necessarily its form. Evaporation turns the mud to normal dirt over a period of days. The exact time depends on exposure to the sun, wind, and normal drainage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Transmute Rock to Mud\" level=\"5\"><p><h5>Transmute Rock to Mud</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Up to two 10-ft. cubes/level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell turns natural, uncut or unworked rock of any sort into an equal volume of mud. Magical stone is not affected by the spell. The depth of the mud created cannot exceed 10 feet. A creature unable to levitate, fly, or otherwise free itself from the mud sinks until hip- or chest-deep, reducing its speed to 5 feet and causing a -2 penalty on attack rolls and AC. Brush thrown atop the mud can support creatures able to climb on top of it. Creatures large enough to walk on the bottom can wade through the area at a speed of 5 feet.</p><p>If <i>transmute rock to mud</i> is cast upon the ceiling of a cavern or tunnel, the mud falls to the floor and spreads out in a pool at a depth of 5 feet. The falling mud and the ensuing cave-in deal 8d6 points of bludgeoning damage to anyone caught directly beneath the area, or half damage to those who succeed on Reflex saves.</p><p>Castles and large stone buildings are generally immune to the effect of the spell, since <i>transmute rock to mud</i> can\'t affect worked stone and doesn\'t reach deep enough to undermine such buildings\' foundations. However, small buildings or structures often rest upon foundations shallow enough to be damaged or even partially toppled by this spell.</p><p>The mud remains until a successful <i>dispel magic</i> or <i>Transmute mud to rock</i> spell restores its substance-but not necessarily its form. Evaporation turns the mud to normal dirt over a period of days. The exact time depends on exposure to the sun, wind, and normal drainage.</p><p><i>Arcane Material Component:</i> Clay and water.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (658,'Transport via Plants','transport via plants','Conjuration','Teleportation',NULL,NULL,'Druid 6','V, S','1 standard action','Unlimited','You and touched objects or other touched willing creatures',NULL,NULL,'1 round','None','No','Move instantly from one plant to another of the same kind.',NULL,NULL,NULL,NULL,'\n      <p>You can enter any normal plant (Medium or larger) and pass any distance to a plant of the same kind in a single round, regardless of the distance separating the two. The entry plant must be alive. The destination plant need not be familiar to you, but it also must be alive. If you are uncertain of the location of a particular kind of destination plant, you need merely designate direction and distance and the <i>transport via plants</i> spell moves you as close as possible to the desired location. If a particular destination plant is desired but the plant is not living, the spell fails and you are ejected from the entry plant.</p>\n      <p>You can bring along objects as long as their weight doesn\'t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. Use the following equivalents to determine the maximum number of larger creatures you can bring along: A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you.</p>\n      <p>You can\'t use this spell to travel through plant creatures.</p>\n      <p>The destruction of an occupied plant slays you and any creatures you have brought along, and ejects the bodies and all carried objects from the tree.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Transport via Plants\" level=\"5\"><p><h5>Transport via Plants</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Unlimited<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You and touched objects or other touched willing creatures<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can enter any normal plant (Medium or larger) and pass any distance to a plant of the same kind in a single round, regardless of the distance separating the two. The entry plant must be alive. The destination plant need not be familiar to you, but it also must be alive. If you are uncertain of the location of a particular kind of destination plant, you need merely designate direction and distance and the <i>transport via plants</i> spell moves you as close as possible to the desired location. If a particular destination plant is desired but the plant is not living, the spell fails and you are ejected from the entry plant.</p><p>You can bring along objects as long as their weight doesn\'t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. Use the following equivalents to determine the maximum number of larger creatures you can bring along: A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you.</p><p>You can\'t use this spell to travel through plant creatures.</p><p>The destruction of an occupied plant slays you and any creatures you have brought along, and ejects the bodies and all carried objects from the tree.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (659,'Trap the Soul','trap the soul','Conjuration','Summoning',NULL,NULL,'Sorcerer/Wizard 8','V, S, M, (F); see text','1 standard action or see text','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Permanent; see text','See text','Yes; see text','Imprisons subject within gem.',NULL,'Before the actual casting of trap the soul, you must procure a gem of at least 1,000 gp value for every Hit Die possessed by the creature to be trapped. If the gem is not valuable enough, it shatters when the entrapment is attempted. (While creatures have no concept of level or Hit Dice as such, the value of the gem needed to trap an individual can be researched. Remember that this value can change over time as creatures gain more Hit Dice.)',NULL,'If the trigger object method is used, a special trigger object, prepared as described above, is needed.','\n      <p><i>Trap the soul</i> forces a creature\'s life force (and its material body) into a gem. The gem holds the trapped entity indefinitely or until the gem is broken and the life force is released, which allows the material body to reform. If the trapped creature is a powerful creature from another plane it can be required to perform a service immediately upon being freed. Otherwise, the creature can go free once the gem imprisoning it is broken.</p>\n      <p>Depending on the version selected, the spell can be triggered in one of two ways.</p>\n      <p><i>Spell Completion:</i> First, the spell can be completed by speaking its final word as a standard action as if you were casting a regular spell at the subject. This allows spell resistance (if any) and a Will save to avoid the effect. If the creature\'s name is spoken as well, any spell resistance is ignored and the save DC increases by 2. If the save or spell resistance is successful, the gem shatters.</p>\n      <p><i>Trigger Object:</i> The second method is far more insidious, for it tricks the subject into accepting a trigger object inscribed with the final spell word, automatically placing the creature\'s soul in the trap. To use this method, both the creature\'s name and the trigger word must be inscribed on the trigger object when the gem is enspelled. A <i>sympathy</i> spell can also be placed on the trigger object. As soon as the subject picks up or accepts the trigger object, its life force is automatically transferred to the gem without the benefit of spell resistance or a save.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Trap the Soul\" level=\"5\"><p><h5>Trap the Soul</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, (F); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action or see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes; see text<br/></td></tr></table><p><i>Trap the soul</i> forces a creature\'s life force (and its material body) into a gem. The gem holds the trapped entity indefinitely or until the gem is broken and the life force is released, which allows the material body to reform. If the trapped creature is a powerful creature from another plane it can be required to perform a service immediately upon being freed. Otherwise, the creature can go free once the gem imprisoning it is broken.</p><p>Depending on the version selected, the spell can be triggered in one of two ways.</p><p><i>Spell Completion:</i> First, the spell can be completed by speaking its final word as a standard action as if you were casting a regular spell at the subject. This allows spell resistance (if any) and a Will save to avoid the effect. If the creature\'s name is spoken as well, any spell resistance is ignored and the save DC increases by 2. If the save or spell resistance is successful, the gem shatters.</p><p><i>Trigger Object:</i> The second method is far more insidious, for it tricks the subject into accepting a trigger object inscribed with the final spell word, automatically placing the creature\'s soul in the trap. To use this method, both the creature\'s name and the trigger word must be inscribed on the trigger object when the gem is enspelled. A <i>sympathy</i> spell can also be placed on the trigger object. As soon as the subject picks up or accepts the trigger object, its life force is automatically transferred to the gem without the benefit of spell resistance or a save.</p><p><i>Material Component:</i> Before the actual casting of <i>trap the soul</i>,  you must procure a gem of at least 1,000 gp value for every Hit Die possessed by the creature to be trapped. If the gem is not valuable enough, it shatters when the entrapment is attempted. (While creatures have no concept of level or Hit Dice as such, the value of the gem needed to trap an individual can be researched. Remember that this value can change over time as creatures gain more Hit Dice.)</p><p><i>Focus (Trigger Object Only):</i> If the trigger object method is used, a special trigger object, prepared as described above, is needed.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (660,'Tree Shape','tree shape','Transmutation',NULL,NULL,NULL,'Druid 2, Ranger 3','V, S, DF','1 standard action','Personal','You',NULL,NULL,'1 hour/level (D)',NULL,NULL,'You look exactly like a tree for 1 hour/level.',NULL,NULL,NULL,NULL,'\n      <p>By means of this spell, you are able to assume the form of a Large living tree or shrub or a Large dead tree trunk with a small number of limbs. The closest inspection cannot reveal that the tree in question is actually a magically concealed creature. To all normal tests you are, in fact, a tree or shrub, although a <i>detect magic</i> spell reveals a faint transmutation on the tree. While in tree form, you can observe all that transpires around you just as if you were in your normal form, and your hit points and save bonuses remain unaffected. You gain a +10 natural armor bonus to AC but have an effective Dexterity score of 0 and a speed of 0 feet. You are immune to critical hits while in tree form. All clothing and gear carried or worn changes with you.</p>\n      <p>You can dismiss <i>tree shape</i> as a free action (instead of as a standard action).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Tree Shape\" level=\"5\"><p><h5>Tree Shape</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 2, Ranger 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr></table><p>By means of this spell, you are able to assume the form of a Large living tree or shrub or a Large dead tree trunk with a small number of limbs. The closest inspection cannot reveal that the tree in question is actually a magically concealed creature. To all normal tests you are, in fact, a tree or shrub, although a <i>detect magic</i> spell reveals a faint transmutation on the tree. While in tree form, you can observe all that transpires around you just as if you were in your normal form, and your hit points and save bonuses remain unaffected. You gain a +10 natural armor bonus to AC but have an effective Dexterity score of 0 and a speed of 0 feet. You are immune to critical hits while in tree form. All clothing and gear carried or worn changes with you.</p><p>You can dismiss <i>tree shape</i> as a free action (instead of as a standard action).</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (661,'Tree Stride','tree stride','Conjuration','Teleportation',NULL,NULL,'Druid 5, Ranger 4','V, S, DF','1 standard action','Personal','You',NULL,NULL,'1 hour/level or until expended; see text',NULL,NULL,'Step from one tree to another far away.',NULL,NULL,NULL,NULL,'\n      <p>You gain the ability to enter trees and move from inside one tree to inside another tree. The first tree you enter and all others you enter must be of the same kind, must be living, and must have girth at least equal to yours. By moving into an oak tree (for example), you instantly know the location of all other oak trees within transport range (see below) and may choose whether you want to pass into one or simply step back out of the tree you moved into. You may choose to pass to any tree of the appropriate kind within the transport range as shown on the following table.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Type of Tree</b><br/></td>\n<td><b>Transport Range</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Oak, ash, yew<br/></td>\n<td>3,000 feet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Elm, linden<br/></td>\n<td>2,000 feet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Other deciduous<br/></td>\n<td>1,500 feet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Any coniferous<br/></td>\n<td>1,000 feet<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>All other trees<br/></td>\n<td>500 feet<br/></td>\n\n</tr>\n</table>\n      <p>You may move into a tree up to one time per caster level (passing from one tree to another counts only as moving into one tree). The spell lasts until the duration expires or you exit a tree. Each transport is a full-round action.</p>\n      <p>You can, at your option, remain within a tree without transporting yourself, but you are forced out when the spell ends. If the tree in which you are concealed is chopped down or burned, you are slain if you do not exit before the process is complete.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Tree Stride\" level=\"5\"><p><h5>Tree Stride</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Ranger 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level or until expended; see text<br/></td></tr></table><p>You gain the ability to enter trees and move from inside one tree to inside another tree. The first tree you enter and all others you enter must be of the same kind, must be living, and must have girth at least equal to yours. By moving into an oak tree (for example), you instantly know the location of all other oak trees within transport range (see below) and may choose whether you want to pass into one or simply step back out of the tree you moved into. You may choose to pass to any tree of the appropriate kind within the transport range as shown on the following table.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Type of Tree</b><br/></td>\n<td><b>Transport Range</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Oak, ash, yew<br/></td>\n<td>3,000 feet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Elm, linden<br/></td>\n<td>2,000 feet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Other deciduous<br/></td>\n<td>1,500 feet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Any coniferous<br/></td>\n<td>1,000 feet<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>All other trees<br/></td>\n<td>500 feet<br/></td>\n\n</tr>\n</table><p>You may move into a tree up to one time per caster level (passing from one tree to another counts only as moving into one tree). The spell lasts until the duration expires or you exit a tree. Each transport is a full-round action.</p><p>You can, at your option, remain within a tree without transporting yourself, but you are forced out when the spell ends. If the tree in which you are concealed is chopped down or burned, you are slain if you do not exit before the process is complete.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (662,'True Resurrection','true resurrection','Conjuration','Healing',NULL,NULL,'Cleric 9','V, S, M, DF','10 minutes','Touch','Dead creature touched',NULL,NULL,'Instantaneous','None; see text','Yes (harmless)','As resurrection, plus remains aren\'t needed.',NULL,'A sprinkle of holy water and diamonds worth a total of at least 25,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>raise dead</i>,  except that you can resurrect a creature that has been dead for as long as 10 years per caster level. This spell can even bring back creatures whose bodies have been destroyed, provided that you unambiguously identify the deceased in some fashion (reciting the deceased\'s time and place of birth or death is the most common method).</p>\n      <p>Upon completion of the spell, the creature is immediately restored to full hit points, vigor, and health, with no loss of level (or Constitution points) or prepared spells.</p>\n      <p>You can revive someone killed by a death effect or someone who has been turned into an undead creature and then destroyed. This spell can also resurrect elementals or outsiders, but it can\'t resurrect constructs or undead creatures.</p>\n      <p>Even <i>true resurrection</i> can\'t restore to life a creature who has died of old age.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"True Resurrection\" level=\"5\"><p><h5>True Resurrection</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr></table><p>This spell functions like <i>raise dead</i>,  except that you can resurrect a creature that has been dead for as long as 10 years per caster level. This spell can even bring back creatures whose bodies have been destroyed, provided that you unambiguously identify the deceased in some fashion (reciting the deceased\'s time and place of birth or death is the most common method).</p><p>Upon completion of the spell, the creature is immediately restored to full hit points, vigor, and health, with no loss of level (or Constitution points) or prepared spells.</p><p>You can revive someone killed by a death effect or someone who has been turned into an undead creature and then destroyed. This spell can also resurrect elementals or outsiders, but it can\'t resurrect constructs or undead creatures.</p><p>Even <i>true resurrection</i> can\'t restore to life a creature who has died of old age.</p><p><i>Material Component:</i> A sprinkle of holy water and diamonds worth a total of at least 25,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (663,'True Seeing','true seeing','Divination',NULL,NULL,NULL,'Cleric 5, Druid 7, Knowledge 5, Sorcerer/Wizard 6','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes (harmless)','Lets you see all things as they really are.',NULL,'An ointment for the eyes that costs 250 gp and is made from mushroom powder, saffron, and fat.',NULL,NULL,'\n      <p>You confer on the subject the ability to see all things as they actually are. The subject sees through normal and magical darkness, notices secret doors hidden by magic, sees the exact locations of creatures or objects under <i>blur</i> or <i>displacement</i> effects, sees invisible creatures or objects normally, sees through illusions, and sees the true form of polymorphed, changed, or transmuted things. Further, the subject can focus its vision to see into the Ethereal Plane (but not into extradimensional spaces). The range of <i>True seeing</i> conferred is 120 feet.</p>\n      <p><i>True seeing</i>, however, does not penetrate solid objects. It in no way confers X-ray vision or its equivalent. It does not negate concealment, including that caused by fog and the like. <i>True seeing</i> does not help the viewer see through mundane disguises, spot creatures who are simply hiding, or notice secret doors hidden by mundane means. In addition, the spell effects cannot be further enhanced with known magic, so one cannot use <i>True seeing</i> through a <i>crystal ball</i> or in conjunction with <i>clairaudience/clairvoyance</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"True Seeing\" level=\"5\"><p><h5>True Seeing</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Druid 7, Knowledge 5, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>You confer on the subject the ability to see all things as they actually are. The subject sees through normal and magical darkness, notices secret doors hidden by magic, sees the exact locations of creatures or objects under <i>blur</i> or <i>displacement</i> effects, sees invisible creatures or objects normally, sees through illusions, and sees the true form of polymorphed, changed, or transmuted things. Further, the subject can focus its vision to see into the Ethereal Plane (but not into extradimensional spaces). The range of <i>True seeing</i> conferred is 120 feet.</p><p><i>True seeing</i>, however, does not penetrate solid objects. It in no way confers X-ray vision or its equivalent. It does not negate concealment, including that caused by fog and the like. <i>True seeing</i> does not help the viewer see through mundane disguises, spot creatures who are simply hiding, or notice secret doors hidden by mundane means. In addition, the spell effects cannot be further enhanced with known magic, so one cannot use <i>True seeing</i> through a <i>crystal ball</i> or in conjunction with <i>clairaudience/clairvoyance</i>.</p><p><i>Material Component:</i> An ointment for the eyes that costs 250 gp and is made from mushroom powder, saffron, and fat.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (664,'True Strike','true strike','Divination',NULL,NULL,NULL,'Sorcerer/Wizard 1','V, F','1 standard action','Personal','You',NULL,NULL,'See text',NULL,NULL,'+20 on your next attack roll.',NULL,NULL,NULL,'A small wooden replica of an archery target.','\n      <p>You gain temporary, intuitive insight into the immediate future during your next attack. Your next single attack roll (if it is made before the end of the next round) gains a +20 insight bonus. Additionally, you are not affected by the miss chance that applies to attackers trying to strike a concealed target.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"True Strike\" level=\"5\"><p><h5>True Strike</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr></table><p>You gain temporary, intuitive insight into the immediate future during your next attack. Your next single attack roll (if it is made before the end of the next round) gains a +20 insight bonus. Additionally, you are not affected by the miss chance that applies to attackers trying to strike a concealed target.</p><p><i>Focus:</i> A small wooden replica of an archery target.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (665,'Undeath to Death','undeath to death','Necromancy',NULL,'Death',NULL,'Cleric 6, Sorcerer/Wizard 6','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Several undead creatures within a 40-ft. -radius burst',NULL,'Instantaneous','Will negates','Yes','Destroys 1d4/level HD of undead (max 20d4).',NULL,'The powder of a crushed diamond worth at least 500 gp.',NULL,NULL,'\n      <p>This spell functions like <i>circle of death</i>, except that it destroys undead creatures as noted above.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Undeath to Death\" level=\"5\"><p><h5>Undeath to Death</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Several undead creatures within a 40-ft. -radius burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr></table><p>This spell functions like <i>circle of death</i>, except that it destroys undead creatures as noted above.</p><p><i>Material Component:</i> The powder of a crushed diamond worth at least 500 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (666,'Undetectable Alignment','undetectable alignment','Abjuration',NULL,NULL,NULL,'Bard 1, Cleric 2, Paladin 2','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature or object',NULL,NULL,'24 hours','Will negates (object)','Yes (object)','Conceals alignment for 24 hours.',NULL,NULL,NULL,NULL,'\n      <p>An <i>undetectable alignment</i> spell conceals the alignment of an object or a creature from all forms of divination.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Undetectable Alignment\" level=\"5\"><p><h5>Undetectable Alignment</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Cleric 2, Paladin 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature or object<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>An <i>undetectable alignment</i> spell conceals the alignment of an object or a creature from all forms of divination.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (667,'Unhallow','unhallow','Evocation',NULL,'Evil',NULL,'Cleric 5, Druid 5','V, S, M','24 hours','Touch',NULL,'40-ft. radius emanating from the touched point',NULL,'Instantaneous','See text','See text','Designates location as unholy.',NULL,'Herbs, oils, and incense worth at least 1,000 gp, plus 1,000 gp per level of the spell to be tied to the unhallowed area.',NULL,NULL,'\n      <p><i>unhallow</i> makes a particular site, building, or structure an unholy site. This has three major effects.</p>\n      <p>First, the site or structure is guarded by a <i>magic circle against good</i> effect.</p>\n      <p>Second, all turning checks made to turn undead take a -4 penalty, and turning checks to rebuke undead gain a +4 profane bonus. Spell resistance does not apply to this effect. (This provision does not apply to the druid version of the spell.)</p>\n      <p>Finally, you may choose to fix a single spell effect to the <i>unhallowed</i> site. The spell effect lasts for one year and functions throughout the entire site, regardless of its normal duration and area or effect. You may designate whether the effect applies to all creatures, creatures that share your faith or alignment, or creatures that adhere to another faith or alignment. At the end of the year, the chosen effect lapses, but it can be renewed or replaced simply by casting <i>unhallow</i> again.</p>\n      <p>Spell effects that may be tied to an <i>unhallowed</i> site include <i>aid</i>,  <i>bane</i>,  <i>bless</i>,  <i>cause fear</i>,  <i>darkness</i>,  <i>daylight</i>,  <i>death ward</i>,  <i>deeper darkness</i>,  <i>detect magic</i>,  <i>detect good</i>,  <i>dimensional anchor</i>,  <i>discern lies</i>,  <i>dispel magic</i>,  <i>endure elements</i>,  <i>freedom of movement</i>,  <i>invisibility purge</i>,  <i>protection from energy</i>,  <i>remove fear</i>,  <i>resist energy</i>,  <i>silence</i>,  <i>tongues</i>,  and <i>zone of truth</i>.</p>\n      <p>Saving throws and spell resistance might apply to these spells\' effects. (See the individual spell descriptions for details.)</p>\n      <p>An area can receive only one <i>unhallow</i> spell (and its associated spell effect) at a time.</p>\n      <p><i>unhallow</i> counters but does not dispel <i>hallow</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Unhallow\" level=\"5\"><p><h5>Unhallow</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Druid 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>40-ft. radius emanating from the touched point<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>See text<br/></td></tr></table><p><i>unhallow</i> makes a particular site, building, or structure an unholy site. This has three major effects.</p><p>First, the site or structure is guarded by a <i>magic circle against good</i> effect.</p><p>Second, all turning checks made to turn undead take a -4 penalty, and turning checks to rebuke undead gain a +4 profane bonus. Spell resistance does not apply to this effect. (This provision does not apply to the druid version of the spell.)</p><p>Finally, you may choose to fix a single spell effect to the <i>unhallowed</i> site. The spell effect lasts for one year and functions throughout the entire site, regardless of its normal duration and area or effect. You may designate whether the effect applies to all creatures, creatures that share your faith or alignment, or creatures that adhere to another faith or alignment. At the end of the year, the chosen effect lapses, but it can be renewed or replaced simply by casting <i>unhallow</i> again.</p><p>Spell effects that may be tied to an <i>unhallowed</i> site include <i>aid</i>,  <i>bane</i>,  <i>bless</i>,  <i>cause fear</i>,  <i>darkness</i>,  <i>daylight</i>,  <i>death ward</i>,  <i>deeper darkness</i>,  <i>detect magic</i>,  <i>detect good</i>,  <i>dimensional anchor</i>,  <i>discern lies</i>,  <i>dispel magic</i>,  <i>endure elements</i>,  <i>freedom of movement</i>,  <i>invisibility purge</i>,  <i>protection from energy</i>,  <i>remove fear</i>,  <i>resist energy</i>,  <i>silence</i>,  <i>tongues</i>,  and <i>zone of truth</i>.</p><p>Saving throws and spell resistance might apply to these spells\' effects. (See the individual spell descriptions for details.)</p><p>An area can receive only one <i>unhallow</i> spell (and its associated spell effect) at a time.</p><p><i>unhallow</i> counters but does not dispel <i>hallow</i>.</p><p><i>Material Component:</i> Herbs, oils, and incense worth at least 1,000 gp, plus 1,000 gp per level of the spell to be tied to the <i>unhallowed</i> area.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (668,'Unholy Aura','unholy aura','Abjuration',NULL,'Evil',NULL,'Cleric 8, Evil 8','V, S, F','1 standard action','20 ft.','One creature/level in a 20-ft. -radius burst centered on you',NULL,NULL,'1 round/level (D)','See text','Yes (harmless)','+4 to AC, +4 resistance, spell resistance 25 against good spells.',NULL,NULL,NULL,'A tiny reliquary containing some sacred relic, such as a piece of parchment from an unholy text. The reliquary costs at least 500 gp.','\n      <p>A malevolent darkness surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by good creatures, and weakening good creatures when they strike the subjects. This abjuration has four effects.</p>\n      <p>First, each warded creature gains a +4 deflection bonus to AC and a +4 resistance bonus on saves. Unlike the effect of <i>protection from good</i>, this benefit applies against all attacks, not just against attacks by good creatures.</p>\n      <p>Second, a warded creature gains spell resistance 25 against good spells and spells cast by good creatures.</p>\n      <p>Third, the abjuration blocks possession and mental influence, just as <i>protection from good</i> does.</p>\n      <p>Finally, if a good creature succeeds on a melee attack against a warded creature, the offending attacker takes 1d6 points of temporary Strength damage (Fortitude negates).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Unholy Aura\" level=\"5\"><p><h5>Unholy Aura</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Evil 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>20 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level in a 20-ft. -radius burst centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>A malevolent darkness surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by good creatures, and weakening good creatures when they strike the subjects. This abjuration has four effects.</p><p>First, each warded creature gains a +4 deflection bonus to AC and a +4 resistance bonus on saves. Unlike the effect of <i>protection from good</i>, this benefit applies against all attacks, not just against attacks by good creatures.</p><p>Second, a warded creature gains spell resistance 25 against good spells and spells cast by good creatures.</p><p>Third, the abjuration blocks possession and mental influence, just as <i>protection from good</i> does.</p><p>Finally, if a good creature succeeds on a melee attack against a warded creature, the offending attacker takes 1d6 points of temporary Strength damage (Fortitude negates).</p><p><i>Focus:</i> A tiny reliquary containing some sacred relic, such as a piece of parchment from an unholy text. The reliquary costs at least 500 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (669,'Unholy Blight','unholy blight','Evocation',NULL,'Evil',NULL,'Evil 4','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'20-ft. -radius spread',NULL,'Instantaneous (1d4 rounds); see text','Will partial','Yes','Damages and sickens good creatures.',NULL,NULL,NULL,NULL,'\n      <p>You call up unholy power to smite your enemies. The power takes the form of a cold, cloying miasma of greasy darkness.</p>\n      <p>Only good and neutral (not evil) creatures are harmed by the spell.</p>\n      <p>The spell deals 1d8 points of damage per two caster levels (maximum 5d8) to a good creature (or 1d6 per caster level, maximum 10d6, to a good outsider) and causes it to be sickened for 1d4 rounds. A successful Will save reduces damage to half and negates the sickened effect. The effects cannot be negated by <i>remove disease</i> or <i>heal</i>,  but <i>remove curse</i> is effective.</p>\n      <p>The spell deals only half damage to creatures who are neither evil nor good, and they are not sickened. Such a creature can reduce the damage in half again (down to one-quarter) with a successful Will save.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Unholy Blight\" level=\"5\"><p><h5>Unholy Blight</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Evil 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous (1d4 rounds); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You call up unholy power to smite your enemies. The power takes the form of a cold, cloying miasma of greasy darkness.</p><p>Only good and neutral (not evil) creatures are harmed by the spell.</p><p>The spell deals 1d8 points of damage per two caster levels (maximum 5d8) to a good creature (or 1d6 per caster level, maximum 10d6, to a good outsider) and causes it to be sickened for 1d4 rounds. A successful Will save reduces damage to half and negates the sickened effect. The effects cannot be negated by <i>remove disease</i> or <i>heal</i>,  but <i>remove curse</i> is effective.</p><p>The spell deals only half damage to creatures who are neither evil nor good, and they are not sickened. Such a creature can reduce the damage in half again (down to one-quarter) with a successful Will save.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (670,'Unseen Servant','unseen servant','Conjuration','Creation',NULL,NULL,'Bard 1, Sorcerer/Wizard 1','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One invisible, mindless, shapeless servant','1 hour/level','None','No','Invisible force obeys your commands.',NULL,'A piece of string and a bit of wood.',NULL,NULL,'\n      <p>An <i>unseen servant</i> is an invisible, mindless, shapeless force that performs simple tasks at your command. It can run and fetch things, open unstuck doors, and hold chairs, as well as clean and mend. The servant can perform only one activity at a time, but it repeats the same activity over and over again if told to do so as long as you remain within range. It can open only normal doors, drawers, lids, and the like. It has an effective Strength score of 2 (so it can lift 20 pounds or drag 100 pounds). It can trigger traps and such, but it can exert only 20 pounds of force, which is not enough to activate certain pressure plates and other devices. It can\'t perform any task that requires a skill check with a DC higher than 10 or that requires a check using a skill that can\'t be used untrained. Its speed is 15 feet.</p>\n      <p>The servant cannot attack in any way; it is never allowed an attack roll. It cannot be killed, but it dissipates if it takes 6 points of damage from area attacks. (It gets no saves against attacks.) If you attempt to send it beyond the spell\'s range (measured from your current position), the servant ceases to exist.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Unseen Servant\" level=\"5\"><p><h5>Unseen Servant</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One invisible, mindless, shapeless servant<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>An <i>unseen servant</i> is an invisible, mindless, shapeless force that performs simple tasks at your command. It can run and fetch things, open unstuck doors, and hold chairs, as well as clean and mend. The servant can perform only one activity at a time, but it repeats the same activity over and over again if told to do so as long as you remain within range. It can open only normal doors, drawers, lids, and the like. It has an effective Strength score of 2 (so it can lift 20 pounds or drag 100 pounds). It can trigger traps and such, but it can exert only 20 pounds of force, which is not enough to activate certain pressure plates and other devices. It can\'t perform any task that requires a skill check with a DC higher than 10 or that requires a check using a skill that can\'t be used untrained. Its speed is 15 feet.</p><p>The servant cannot attack in any way; it is never allowed an attack roll. It cannot be killed, but it dissipates if it takes 6 points of damage from area attacks. (It gets no saves against attacks.) If you attempt to send it beyond the spell\'s range (measured from your current position), the servant ceases to exist.</p><p><i>Material Component:</i> A piece of string and a bit of wood.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (671,'Vampiric Touch','vampiric touch','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 3','V, S','1 standard action','Touch','Living creature touched',NULL,NULL,'Instantaneous/1 hour; see text','None','Yes','Touch deals 1d6/two levels damage; caster gains damage as hp.',NULL,NULL,NULL,NULL,'\n      <p>You must succeed on a melee touch attack. Your touch deals 1d6 points of damage per two caster levels (maximum 10d6). You gain temporary hit points equal to the damage you deal. However, you can\'t gain more than the subject\'s current hit points +10, which is enough to kill the subject. The temporary hit points disappear 1 hour later.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Vampiric Touch\" level=\"5\"><p><h5>Vampiric Touch</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous/1 hour; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You must succeed on a melee touch attack. Your touch deals 1d6 points of damage per two caster levels (maximum 10d6). You gain temporary hit points equal to the damage you deal. However, you can\'t gain more than the subject\'s current hit points +10, which is enough to kill the subject. The temporary hit points disappear 1 hour later.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (672,'Veil','veil','Illusion','Glamer',NULL,NULL,'Bard 6, Sorcerer/Wizard 6','V, S','1 standard action','Long (400 ft. + 40 ft./level)','One or more creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'Concentration + 1 hour/level (D)','Will negates; see text','Yes; see text','Changes appearance of group of creatures.',NULL,NULL,NULL,NULL,'\n      <p>You instantly change the appearance of the subjects and then maintain that appearance for the spell\'s duration. You can make the subjects appear to be anything you wish. The subjects look, feel, and smell just like the creatures the spell makes them resemble. Affected creatures resume their normal appearances if slain. You must succeed on a Disguise check to duplicate the appearance of a specific individual. This spell gives you a +10 bonus on the check.</p>\n      <p>Unwilling targets can negate the spell\'s effect on them by making Will saves or with spell resistance. Those who interact with the subjects can attempt Will disbelief saves to see through the glamer, but spell resistance doesn\'t help.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Veil\" level=\"5\"><p><h5>Veil</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One or more creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration + 1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes; see text<br/></td></tr></table><p>You instantly change the appearance of the subjects and then maintain that appearance for the spell\'s duration. You can make the subjects appear to be anything you wish. The subjects look, feel, and smell just like the creatures the spell makes them resemble. Affected creatures resume their normal appearances if slain. You must succeed on a Disguise check to duplicate the appearance of a specific individual. This spell gives you a +10 bonus on the check.</p><p>Unwilling targets can negate the spell\'s effect on them by making Will saves or with spell resistance. Those who interact with the subjects can attempt Will disbelief saves to see through the glamer, but spell resistance doesn\'t help.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (673,'Ventriloquism','ventriloquism','Illusion','Figment',NULL,NULL,'Bard 1, Sorcerer/Wizard 1','V, F','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Intelligible sound, usually speech','1 min./level (D)','Will disbelief (if interacted with)','No','Throws voice for 1 min./level.',NULL,NULL,NULL,'A parchment rolled up into a small cone.','\n      <p>You can make your voice (or any sound that you can normally make vocally) seem to issue from someplace else. You can speak in any language you know. With respect to such voices and sounds, anyone who hears the sound and rolls a successful save recognizes it as illusory (but still hears it).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Ventriloquism\" level=\"5\"><p><h5>Ventriloquism</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Figment)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Intelligible sound, usually speech<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will disbelief (if interacted with)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can make your voice (or any sound that you can normally make vocally) seem to issue from someplace else. You can speak in any language you know. With respect to such voices and sounds, anyone who hears the sound and rolls a successful save recognizes it as illusory (but still hears it).</p><p><i>Focus:</i> A parchment rolled up into a small cone.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (674,'Virtue','virtue','Transmutation',NULL,NULL,NULL,'Cleric 0, Druid 0, Paladin 1','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 min.','Fortitude negates (harmless)','Yes (harmless)','Subject gains 1 temporary hp.',NULL,NULL,NULL,NULL,'\n      <p>The subject gains 1 temporary hit point.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Virtue\" level=\"5\"><p><h5>Virtue</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 0, Druid 0, Paladin 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject gains 1 temporary hit point.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (675,'Vision','vision','Divination',NULL,NULL,NULL,'Sorcerer/Wizard 7','V, S, M, XP','1 standard action','Personal','You',NULL,NULL,'See text',NULL,NULL,'As legend lore, but quicker and strenuous.',NULL,'Incense worth at least 250 gp.',NULL,'Four strips of ivory (worth 50 gp each) formed into a rectangle.','\n      <p>This spell functions like <i>legend lore</i>,  except that it works more quickly but produces some strain on you. You pose a question about some person, place, or object, then cast the spell. If the person or object is at hand or if you are in the place in question, you receive a vision about it by succeeding on a caster level check (1d20 +1 per caster level; maximum +25) against DC 20. If only detailed information on the person, place, or object is known, the DC is 25, and the information gained is incomplete. If only rumors are known, the DC is 30, and the information gained is vague.</p>\n      <p/>\n    ','100 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Vision\" level=\"5\"><p><h5>Vision</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr></table><p>This spell functions like <i>legend lore</i>,  except that it works more quickly but produces some strain on you. You pose a question about some person, place, or object, then cast the spell. If the person or object is at hand or if you are in the place in question, you receive a vision about it by succeeding on a caster level check (1d20 +1 per caster level; maximum +25) against DC 20. If only detailed information on the person, place, or object is known, the DC is 25, and the information gained is incomplete. If only rumors are known, the DC is 30, and the information gained is vague.</p><p><i>XP Cost:</i> 100 XP.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (676,'Wail of the Banshee','wail of the banshee','Necromancy',NULL,'Death, Sonic',NULL,'Death 9, Sorcerer/Wizard 9','V','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'One living creature/level within a 40-ft. -radius spread',NULL,'Instantaneous','Fortitude negates','Yes','Kills one creature/level.',NULL,NULL,NULL,NULL,'\n      <p>You emit a terrible scream that kills creatures that hear it (except for yourself ). Creatures closest to the point of origin are affected first.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wail of the Banshee\" level=\"5\"><p><h5>Wail of the Banshee</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death, Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Death 9, Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>One living creature/level within a 40-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You emit a terrible scream that kills creatures that hear it (except for yourself ). Creatures closest to the point of origin are affected first.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (677,'Wall of Fire','wall of fire','Evocation',NULL,'Fire',NULL,'Druid 5, Fire 4, Sorcerer/Wizard 4','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Opaque sheet of flame up to 20 ft. long/level or a ring of fire with a radius of up to 5 ft. per two levels; either form 20 ft. high','Concentration + 1 round/level','None','Yes','Deals 2d4 fire damage out to 10 ft. and 1d4 out to 20 ft. Passing through wall deals 2d6 damage +1/level.',NULL,NULL,'A small piece of phosphorus.',NULL,'\n      <p>An immobile, blazing curtain of shimmering violet fire springs into existence. One side of the wall, selected by you, sends forth waves of heat, dealing 2d4 points of fire damage to creatures within 10 feet and 1d4 points of fire damage to those past 10 feet but within 20 feet. The wall deals this damage when it appears and on your turn each round to all creatures in the area. In addition, the wall deals 2d6 points of fire damage +1 point of fire damage per caster level (maximum +20) to any creature passing through it. The wall deals double damage to undead creatures.</p>\n      <p>If you evoke the wall so that it appears where creatures are, each creature takes damage as if passing through the wall. If any 5-foot length of wall takes 20 points of cold damage or more in 1 round, that length goes out. (Do not divide cold damage by 4, as normal for objects.)</p>\n      <p><i>Wall of fire</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>Wall of fire</i> that is extinguished by cold damage becomes inactive for 10 minutes, then reforms at normal strength.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wall of Fire\" level=\"5\"><p><h5>Wall of Fire</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Fire 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Opaque sheet of flame up to 20 ft. long/level or a ring of fire with a radius of up to 5 ft. per two levels; either form 20 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration + 1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>An immobile, blazing curtain of shimmering violet fire springs into existence. One side of the wall, selected by you, sends forth waves of heat, dealing 2d4 points of fire damage to creatures within 10 feet and 1d4 points of fire damage to those past 10 feet but within 20 feet. The wall deals this damage when it appears and on your turn each round to all creatures in the area. In addition, the wall deals 2d6 points of fire damage +1 point of fire damage per caster level (maximum +20) to any creature passing through it. The wall deals double damage to undead creatures.</p><p>If you evoke the wall so that it appears where creatures are, each creature takes damage as if passing through the wall. If any 5-foot length of wall takes 20 points of cold damage or more in 1 round, that length goes out. (Do not divide cold damage by 4, as normal for objects.)</p><p><i>Wall of fire</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>Wall of fire</i> that is extinguished by cold damage becomes inactive for 10 minutes, then reforms at normal strength.</p><p><i>Arcane Material Component:</i> A small piece of phosphorus.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (678,'Wall of Force','wall of force','Evocation',NULL,'Force',NULL,'Sorcerer/Wizard 5','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Wall whose area is up to one 10-ft. square/level','1 round /level (D)','None','No','Wall is immune to damage.',NULL,'A pinch of powder made from a clear gem.',NULL,NULL,'\n      <p>A <i>wall of force</i> spell creates an invisible wall of force. The wall cannot move, it is immune to damage of all kinds, and it is unaffected by most spells, including <i>dispel magic</i>. However, <i>disintegrate</i> immediately destroys it, as does a <i>rod of cancellation</i>, a <i>sphere of annihilation</i>,  or a <i>mage\'s disjunction</i> spell. Breath weapons and spells cannot pass through the wall in either direction, although <i>dimension door</i>,  <i>teleport</i>,  and similar effects can bypass the barrier. It blocks ethereal creatures as well as material ones (though ethereal creatures can usually get around the wall by floating under or over it through material floors and ceilings). Gaze attacks can operate through a <i>wall of force</i>.</p>\n      <p>The caster can form the wall into a flat, vertical plane whose area is up to one 10- foot square per level. The wall must be continuous and unbroken when formed. If its surface is broken by any object or creature, the spell fails.</p>\n      <p><i>wall of force</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wall of Force\" level=\"5\"><p><h5>Wall of Force</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Wall whose area is up to one 10-ft. square/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round /level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A <i>wall of force</i> spell creates an invisible wall of force. The wall cannot move, it is immune to damage of all kinds, and it is unaffected by most spells, including <i>dispel magic</i>. However, <i>disintegrate</i> immediately destroys it, as does a <i>rod of cancellation</i>, a <i>sphere of annihilation</i>,  or a <i>mage\'s disjunction</i> spell. Breath weapons and spells cannot pass through the wall in either direction, although <i>dimension door</i>,  <i>teleport</i>,  and similar effects can bypass the barrier. It blocks ethereal creatures as well as material ones (though ethereal creatures can usually get around the wall by floating under or over it through material floors and ceilings). Gaze attacks can operate through a <i>wall of force</i>.</p><p>The caster can form the wall into a flat, vertical plane whose area is up to one 10- foot square per level. The wall must be continuous and unbroken when formed. If its surface is broken by any object or creature, the spell fails.</p><p><i>wall of force</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Material Component:</i> A pinch of powder made from a clear gem.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (679,'Wall of Ice','wall of ice','Evocation',NULL,'Cold',NULL,'Sorcerer/Wizard 4','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Anchored plane of ice, up to one 10-ft. square/level, or hemisphere of ice with a radius of up to 3 ft. + 1 ft./level','1 min./level','Reflex negates; see text','Yes','Ice plane creates wall with 15 hp +1/level, or hemisphere can trap creatures inside.',NULL,'A small piece of quartz or similar rock crystal.',NULL,NULL,'\n      <p>This spell creates an anchored plane of ice or a hemisphere of ice, depending on the version selected. A <i>wall of ice</i> cannot form in an area occupied by physical objects or creatures. Its surface must be smooth and unbroken when created. Any creature adjacent to the wall when it is created may attempt a Reflex save to disrupt the wall as it is being formed. A successful save indicates that the spell automatically fails. Fire can melt a <i>wall of ice</i>,  and it deals full damage to the wall (instead of the normal half damage taken by objects). Suddenly melting a <i>wall of ice</i> creates a great cloud of steamy fog that lasts for 10 minutes.</p>\n      <p><i>Ice Plane:</i> A sheet of strong, hard ice appears. The wall is 1 inch thick per caster level. It covers up to a 10-foot-square area per caster level (so a 10th-level wizard can create a wall of ice 100 feet long and 10 feet high, a wall 50 feet long and 20 feet high, or some other combination of length and height that does not exceed 1,000 square feet). The plane can be oriented in any fashion as long as it is anchored. A vertical wall need only be anchored on the floor, while a horizontal or slanting wall must be anchored on two opposite sides.</p>\n      <p>Each 10-foot square of wall has 3 hit points per inch of thickness. Creatures can hit the wall automatically. A section of wall whose hit points drop to 0 is breached. If a creature tries to break through the wall with a single attack, the DC for the Strength check is 15 + caster level.</p>\n      <p>Even when the ice has been broken through, a sheet of frigid air remains. Any creature stepping through it (including the one who broke through the wall) takes 1d6 points of cold damage +1 point per caster level (no save).</p>\n      <p><i>Hemisphere:</i> The wall takes the form of a hemisphere whose maximum radius is 3 feet + 1 foot per caster level. The <i>hemisphere</i> is as hard to break through as the <i>ice plane</i> form, but it does not deal damage to those who go through a breach.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wall of Ice\" level=\"5\"><p><h5>Wall of Ice</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Cold]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Anchored plane of ice, up to one 10-ft. square/level, or hemisphere of ice with a radius of up to 3 ft. + 1 ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell creates an anchored plane of ice or a hemisphere of ice, depending on the version selected. A <i>wall of ice</i> cannot form in an area occupied by physical objects or creatures. Its surface must be smooth and unbroken when created. Any creature adjacent to the wall when it is created may attempt a Reflex save to disrupt the wall as it is being formed. A successful save indicates that the spell automatically fails. Fire can melt a <i>wall of ice</i>,  and it deals full damage to the wall (instead of the normal half damage taken by objects). Suddenly melting a <i>wall of ice</i> creates a great cloud of steamy fog that lasts for 10 minutes.</p><p><i>Ice Plane:</i> A sheet of strong, hard ice appears. The wall is 1 inch thick per caster level. It covers up to a 10-foot-square area per caster level (so a 10th-level wizard can create a wall of ice 100 feet long and 10 feet high, a wall 50 feet long and 20 feet high, or some other combination of length and height that does not exceed 1,000 square feet). The plane can be oriented in any fashion as long as it is anchored. A vertical wall need only be anchored on the floor, while a horizontal or slanting wall must be anchored on two opposite sides.</p><p>Each 10-foot square of wall has 3 hit points per inch of thickness. Creatures can hit the wall automatically. A section of wall whose hit points drop to 0 is breached. If a creature tries to break through the wall with a single attack, the DC for the Strength check is 15 + caster level.</p><p>Even when the ice has been broken through, a sheet of frigid air remains. Any creature stepping through it (including the one who broke through the wall) takes 1d6 points of cold damage +1 point per caster level (no save).</p><p><i>Hemisphere:</i> The wall takes the form of a hemisphere whose maximum radius is 3 feet + 1 foot per caster level. The <i>hemisphere</i> is as hard to break through as the <i>ice plane</i> form, but it does not deal damage to those who go through a breach.</p><p><i>Material Component:</i> A small piece of quartz or similar rock crystal.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (680,'Wall of Iron','wall of iron','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 6','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Iron wall whose area is up to one 5-ft. square/level; see text','Instantaneous','See text','No','30 hp/four levels; can topple onto foes.',NULL,'A small piece of sheet iron plus gold dust worth 50 gp (1 pound of gold dust).',NULL,NULL,'\n      <p>You cause a flat, vertical iron wall to spring into being. The wall inserts itself into any surrounding nonliving material if its area is sufficient to do so. The wall cannot be conjured so that it occupies the same space as a creature or another object. It must always be a flat plane, though you can shape its edges to fit the available space.</p>\n      <p>A <i>wall of iron</i> is 1 inch thick per four caster levels. You can double the wall\'s area by halving its thickness. Each 5- foot square of the wall has 30 hit points per inch of thickness and hardness 10. A section of wall whose hit points drop to 0 is breached. If a creature tries to break through the wall with a single attack, the DC for the Strength check is 25 + 2 per inch of thickness.</p>\n      <p>If you desire, the wall can be created vertically resting on a flat surface but not attached to the surface, so that it can be tipped over to fall on and crush creatures beneath it. The wall is 50% likely to tip in either direction if left unpushed. Creatures can push the wall in one direction rather than letting it fall randomly. A creature must make a DC 40 Strength check to push the wall over. Creatures with room to flee the falling wall may do so by making successful Reflex saves. Any Large or smaller creature that fails takes 10d6 points of damage. The wall cannot crush Huge and larger creatures.</p>\n      <p>Like any iron wall, this wall is subject to rust, perforation, and other natural phenomena.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wall of Iron\" level=\"5\"><p><h5>Wall of Iron</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Iron wall whose area is up to one 5-ft. square/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You cause a flat, vertical iron wall to spring into being. The wall inserts itself into any surrounding nonliving material if its area is sufficient to do so. The wall cannot be conjured so that it occupies the same space as a creature or another object. It must always be a flat plane, though you can shape its edges to fit the available space.</p><p>A <i>wall of iron</i> is 1 inch thick per four caster levels. You can double the wall\'s area by halving its thickness. Each 5- foot square of the wall has 30 hit points per inch of thickness and hardness 10. A section of wall whose hit points drop to 0 is breached. If a creature tries to break through the wall with a single attack, the DC for the Strength check is 25 + 2 per inch of thickness.</p><p>If you desire, the wall can be created vertically resting on a flat surface but not attached to the surface, so that it can be tipped over to fall on and crush creatures beneath it. The wall is 50% likely to tip in either direction if left unpushed. Creatures can push the wall in one direction rather than letting it fall randomly. A creature must make a DC 40 Strength check to push the wall over. Creatures with room to flee the falling wall may do so by making successful Reflex saves. Any Large or smaller creature that fails takes 10d6 points of damage. The wall cannot crush Huge and larger creatures.</p><p>Like any iron wall, this wall is subject to rust, perforation, and other natural phenomena.</p><p><i>Material Component:</i> A small piece of sheet iron plus gold dust worth 50 gp (1 pound of gold dust).</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (681,'Wall of Stone','wall of stone','Conjuration','Creation','Earth',NULL,'Cleric 5, Druid 6, Earth 5, Sorcerer/Wizard 5','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Stone wall whose area is up to one 5-ft. square/level (S)','Instantaneous','See text','No','Creates a stone wall that can be shaped.',NULL,NULL,'A small block of granite.',NULL,'\n      <p>This spell creates a wall of rock that merges into adjoining rock surfaces. A <i>wall of stone</i> is 1 inch thick per four caster levels and composed of up to one 5-foot square per level. You can double the wall\'s area by halving its thickness. The wall cannot be conjured so that it occupies the same space as a creature or another object.</p>\n      <p>Unlike a <i>wall of iron</i>,  you can create a <i>wall of stone</i> in almost any shape you desire. The wall created need not be vertical, nor rest upon any firm foundation; however, it must merge with and be solidly supported by existing stone. It can be used to bridge a chasm, for instance, or as a ramp. For this use, if the span is more than 20 feet, the wall must be arched and buttressed. This requirement reduces the spell\'s area by half. The wall can be crudely shaped to allow crenellations, battlements, and so forth by likewise reducing the area.</p>\n      <p>Like any other stone wall, this one can be destroyed by a <i>disintegrate</i> spell or by normal means such as breaking and chipping. Each 5-foot square of the wall has 15 hit points per inch of thickness and hardness 8. A section of wall whose hit points drop to 0 is breached. If a creature tries to break through the wall with a single attack, the DC for the Strength check is 20 + 2 per inch of thickness.</p>\n      <p>It is possible, but difficult, to trap mobile opponents within or under a <i>wall of stone</i>, provided the wall is shaped so it can hold the creatures. Creatures can avoid entrapment with successful Reflex saves.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wall of Stone\" level=\"5\"><p><h5>Wall of Stone</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Druid 6, Earth 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Stone wall whose area is up to one 5-ft. square/level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell creates a wall of rock that merges into adjoining rock surfaces. A <i>wall of stone</i> is 1 inch thick per four caster levels and composed of up to one 5-foot square per level. You can double the wall\'s area by halving its thickness. The wall cannot be conjured so that it occupies the same space as a creature or another object.</p><p>Unlike a <i>wall of iron</i>,  you can create a <i>wall of stone</i> in almost any shape you desire. The wall created need not be vertical, nor rest upon any firm foundation; however, it must merge with and be solidly supported by existing stone. It can be used to bridge a chasm, for instance, or as a ramp. For this use, if the span is more than 20 feet, the wall must be arched and buttressed. This requirement reduces the spell\'s area by half. The wall can be crudely shaped to allow crenellations, battlements, and so forth by likewise reducing the area.</p><p>Like any other stone wall, this one can be destroyed by a <i>disintegrate</i> spell or by normal means such as breaking and chipping. Each 5-foot square of the wall has 15 hit points per inch of thickness and hardness 8. A section of wall whose hit points drop to 0 is breached. If a creature tries to break through the wall with a single attack, the DC for the Strength check is 20 + 2 per inch of thickness.</p><p>It is possible, but difficult, to trap mobile opponents within or under a <i>wall of stone</i>, provided the wall is shaped so it can hold the creatures. Creatures can avoid entrapment with successful Reflex saves.</p><p><i>Arcane Material Component:</i> A small block of granite.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (682,'Wall of Thorns','wall of thorns','Conjuration','Creation',NULL,NULL,'Druid 5, Plant 5','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Wall of thorny brush, up to one 10-ft. cube/level (S)','10 min./level (D)','None','No','Thorns damage anyone who tries to pass.',NULL,NULL,NULL,NULL,'\n      <p>A <i>wall of thorns</i> spell creates a barrier of very tough, pliable, tangled brush bearing needle-sharp thorns as long as a human\'s finger. Any creature forced into or attempting to move through a <i>wall of thorns</i> takes slashing damage per round of movement equal to 25 minus the creature\'s AC. Dexterity and dodge bonuses to AC do not count for this calculation. (Creatures with an Armor Class of 25 or higher, without considering Dexterity and dodge bonuses, take no damage from contact with the wall.)</p>\n      <p>You can make the wall as thin as 5 feet thick, which allows you to shape the wall as a number of 10-by-10-by-5-foot blocks equal to twice your caster level. This has no effect on the damage dealt by the thorns, but any creature attempting to break through takes that much less time to force its way through the barrier.</p>\n      <p>Creatures can force their way slowly through the wall by making a Strength check as a full-round action. For every 5 points by which the check exceeds 20, a creature moves 5 feet (up to a maximum distance equal to its normal land speed). Of course, moving or attempting to move through the thorns incurs damage as described above. A creature trapped in the thorns can choose to remain motionless in order to avoid taking any more damage.</p>\n      <p>Any creature within the area of the spell when it is cast takes damage as if it had moved into the wall and is caught inside. In order to escape, it must attempt to push its way free, or it can wait until the spell ends. Creatures with the ability to pass through overgrown areas unhindered can pass through a <i>wall of thorns</i> at normal speed without taking damage.</p>\n      <p>A <i>wall of thorns</i> can be breached by slow work with edged weapons. Chopping away at the wall creates a safe passage 1 foot deep for every 10 minutes of work. Normal fire cannot harm the barrier, but magical fire burns it away in 10 minutes.</p>\n      <p>Despite its appearance, a <i>wall of thorns</i> is not actually a living plant, and thus is unaffected by spells that affect plants.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wall of Thorns\" level=\"5\"><p><h5>Wall of Thorns</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Plant 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Wall of thorny brush, up to one 10-ft. cube/level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A <i>wall of thorns</i> spell creates a barrier of very tough, pliable, tangled brush bearing needle-sharp thorns as long as a human\'s finger. Any creature forced into or attempting to move through a <i>wall of thorns</i> takes slashing damage per round of movement equal to 25 minus the creature\'s AC. Dexterity and dodge bonuses to AC do not count for this calculation. (Creatures with an Armor Class of 25 or higher, without considering Dexterity and dodge bonuses, take no damage from contact with the wall.)</p><p>You can make the wall as thin as 5 feet thick, which allows you to shape the wall as a number of 10-by-10-by-5-foot blocks equal to twice your caster level. This has no effect on the damage dealt by the thorns, but any creature attempting to break through takes that much less time to force its way through the barrier.</p><p>Creatures can force their way slowly through the wall by making a Strength check as a full-round action. For every 5 points by which the check exceeds 20, a creature moves 5 feet (up to a maximum distance equal to its normal land speed). Of course, moving or attempting to move through the thorns incurs damage as described above. A creature trapped in the thorns can choose to remain motionless in order to avoid taking any more damage.</p><p>Any creature within the area of the spell when it is cast takes damage as if it had moved into the wall and is caught inside. In order to escape, it must attempt to push its way free, or it can wait until the spell ends. Creatures with the ability to pass through overgrown areas unhindered can pass through a <i>wall of thorns</i> at normal speed without taking damage.</p><p>A <i>wall of thorns</i> can be breached by slow work with edged weapons. Chopping away at the wall creates a safe passage 1 foot deep for every 10 minutes of work. Normal fire cannot harm the barrier, but magical fire burns it away in 10 minutes.</p><p>Despite its appearance, a <i>wall of thorns</i> is not actually a living plant, and thus is unaffected by spells that affect plants.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (683,'Warp Wood','warp wood','Transmutation',NULL,NULL,NULL,'Druid 2','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','1 Small wooden object/level, all within a 20-ft. radius',NULL,NULL,'Instantaneous','Will negates (object)','Yes (object)','Bends wood (shaft, handle, door, plank).',NULL,NULL,NULL,NULL,'\n      <p>You cause wood to bend and warp, permanently destroying its straightness, form, and strength. A warped door springs open (or becomes stuck, requiring a Strength check to open, at your option). A boat or ship springs a leak. Warped ranged weapons are useless. A warped melee weapon causes a -4 penalty on attack rolls.</p>\n      <p>You may warp one Small or smaller object or its equivalent per caster level. A Medium object counts as two Small objects, a Large object as four, a Huge object as eight, a Gargantuan object as sixteen, and a Colossal object as thirty-two.</p>\n      <p>Alternatively, you can unwarp wood (effectively warping it back to normal) with this spell, straightening wood that has been warped by this spell or by other means. <i>Make whole</i>, on the other hand, does no good in repairing a warped item.</p>\n      <p>You can combine multiple consecutive <i>warp wood</i> spells to warp (or unwarp) an object that is too large for you to warp with a single spell.</p>\n      <p>Until the object is completely warped, it suffers no ill effects.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Warp Wood\" level=\"5\"><p><h5>Warp Wood</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>1 Small wooden object/level, all within a 20-ft. radius<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>You cause wood to bend and warp, permanently destroying its straightness, form, and strength. A warped door springs open (or becomes stuck, requiring a Strength check to open, at your option). A boat or ship springs a leak. Warped ranged weapons are useless. A warped melee weapon causes a -4 penalty on attack rolls.</p><p>You may warp one Small or smaller object or its equivalent per caster level. A Medium object counts as two Small objects, a Large object as four, a Huge object as eight, a Gargantuan object as sixteen, and a Colossal object as thirty-two.</p><p>Alternatively, you can unwarp wood (effectively warping it back to normal) with this spell, straightening wood that has been warped by this spell or by other means. <i>Make whole</i>, on the other hand, does no good in repairing a warped item.</p><p>You can combine multiple consecutive <i>warp wood</i> spells to warp (or unwarp) an object that is too large for you to warp with a single spell.</p><p>Until the object is completely warped, it suffers no ill effects.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (684,'Water Breathing','water breathing','Transmutation',NULL,NULL,NULL,'Cleric 3, Druid 3, Sorcerer/Wizard 3, Water 3','V, S, M/DF','1 standard action','Touch','Living creatures touched',NULL,NULL,'2 hours/level; see text','Will negates (harmless)','Yes (harmless)','Subjects can breathe underwater.',NULL,NULL,'A short reed or piece of straw.',NULL,'\n      <p>The transmuted creatures can breathe water freely. Divide the duration evenly among all the creatures you touch.</p>\n      <p>The spell does not make creatures unable to breathe air.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Water Breathing\" level=\"5\"><p><h5>Water Breathing</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Druid 3, Sorcerer/Wizard 3, Water 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creatures touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The transmuted creatures can breathe water freely. Divide the duration evenly among all the creatures you touch.</p><p>The spell does not make creatures unable to breathe air.</p><p><i>Arcane Material Component:</i> A short reed or piece of straw.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (685,'Water Walk','water walk','Transmutation',NULL,'Water',NULL,'Cleric 3, Ranger 3','V, S, DF','1 standard action','Touch','One touched creature/level',NULL,NULL,'10 min./level (D)','Will negates (harmless)','Yes (harmless)','Subject treads on water as if solid.',NULL,NULL,NULL,NULL,'\n      <p>The transmuted creatures can tread on any liquid as if it were firm ground. Mud, oil, snow, quicksand, running water, ice, and even lava can be traversed easily, since the subjects\' feet hover an inch or two above the surface. (Creatures crossing molten lava still take damage from the heat because they are near it.) The subjects can walk, run, charge, or otherwise move across the surface as if it were normal ground.</p>\n      <p>If the spell is cast underwater (or while the subjects are partially or wholly submerged in whatever liquid they are in), the subjects are borne toward the surface at 60 feet per round until they can stand on it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Water Walk\" level=\"5\"><p><h5>Water Walk</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Water]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Ranger 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One touched creature/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The transmuted creatures can tread on any liquid as if it were firm ground. Mud, oil, snow, quicksand, running water, ice, and even lava can be traversed easily, since the subjects\' feet hover an inch or two above the surface. (Creatures crossing molten lava still take damage from the heat because they are near it.) The subjects can walk, run, charge, or otherwise move across the surface as if it were normal ground.</p><p>If the spell is cast underwater (or while the subjects are partially or wholly submerged in whatever liquid they are in), the subjects are borne toward the surface at 60 feet per round until they can stand on it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (686,'Waves of Exhaustion','waves of exhaustion','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 7','V, S','1 standard action','60 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','No','Yes','Several targets become exhausted.',NULL,NULL,NULL,NULL,'\n      <p>Waves of negative energy cause all living creatures in the spell\'s area to become exhausted. This spell has no effect on a creature that is already exhausted.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Waves of Exhaustion\" level=\"5\"><p><h5>Waves of Exhaustion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Waves of negative energy cause all living creatures in the spell\'s area to become exhausted. This spell has no effect on a creature that is already exhausted.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (687,'Waves of Fatigue','waves of fatigue','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 5','V, S','1 standard action','30 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','No','Yes','Several targets become fatigued.',NULL,NULL,NULL,NULL,'\n      <p>Waves of negative energy render all living creatures in the spell\'s area fatigued. This spell has no effect on a creature that is already fatigued.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Waves of Fatigue\" level=\"5\"><p><h5>Waves of Fatigue</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>30 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Waves of negative energy render all living creatures in the spell\'s area fatigued. This spell has no effect on a creature that is already fatigued.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (688,'Web','web','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 2','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Webs in a 20-ft. -radius spread','10 min./level (D)','Reflex negates; see text','No','Fills 20-ft. -radius spread with sticky spiderwebs.',NULL,'A bit of spider web.',NULL,NULL,'\n      <p><i>web</i> creates a many-layered mass of strong, sticky strands. These strands trap those caught in them. The strands are similar to spider webs but far larger and tougher. These masses must be anchored to two or more solid and diametrically opposed points or else the web collapses upon itself and disappears. Creatures caught within a <i>web</i> become entangled among the gluey fibers. Attacking a creature in a web won\'t cause you to become entangled.</p>\n      <p>Anyone in the effect\'s area when the spell is cast must make a Reflex save. If this save succeeds, the creature is entangled, but not prevented from moving, though moving is more difficult than normal for being entangled (see below). If the save fails, the creature is entangled and can\'t move from its space, but can break loose by spending 1 round and making a DC 20 Strength check or a DC 25 Escape Artist check. Once loose (either by making the initial Reflex save or a later Strength check or Escape Artist check), a creature remains entangled, but may move through the <i>web</i> very slowly. Each round devoted to moving allows the creature to make a new Strength check or Escape Artist check. The creature moves 5 feet for each full 5 points by which the check result exceeds 10.</p>\n      <p>If you have at least 5 feet of web between you and an opponent, it provides cover. If you have at least 20 feet of web between you, it provides total cover.</p>\n      <p>The strands of a <i>web</i> spell are flammable. A magic <i>flaming sword</i> can slash them away as easily as a hand brushes away cobwebs. Any fire can set the webs alight and burn away 5 square feet in 1 round. All creatures within flaming webs take 2d4 points of fire damage from the flames.</p>\n      <p><i>web</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>web</i> that is damaged (but not destroyed) regrows in 10 minutes.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Web\" level=\"5\"><p><h5>Web</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Webs in a 20-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p><i>web</i> creates a many-layered mass of strong, sticky strands. These strands trap those caught in them. The strands are similar to spider webs but far larger and tougher. These masses must be anchored to two or more solid and diametrically opposed points or else the web collapses upon itself and disappears. Creatures caught within a <i>web</i> become entangled among the gluey fibers. Attacking a creature in a web won\'t cause you to become entangled.</p><p>Anyone in the effect\'s area when the spell is cast must make a Reflex save. If this save succeeds, the creature is entangled, but not prevented from moving, though moving is more difficult than normal for being entangled (see below). If the save fails, the creature is entangled and can\'t move from its space, but can break loose by spending 1 round and making a DC 20 Strength check or a DC 25 Escape Artist check. Once loose (either by making the initial Reflex save or a later Strength check or Escape Artist check), a creature remains entangled, but may move through the <i>web</i> very slowly. Each round devoted to moving allows the creature to make a new Strength check or Escape Artist check. The creature moves 5 feet for each full 5 points by which the check result exceeds 10.</p><p>If you have at least 5 feet of web between you and an opponent, it provides cover. If you have at least 20 feet of web between you, it provides total cover.</p><p>The strands of a <i>web</i> spell are flammable. A magic <i>flaming sword</i> can slash them away as easily as a hand brushes away cobwebs. Any fire can set the webs alight and burn away 5 square feet in 1 round. All creatures within flaming webs take 2d4 points of fire damage from the flames.</p><p><i>web</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>web</i> that is damaged (but not destroyed) regrows in 10 minutes.</p><p><i>Material Component:</i> A bit of spider web.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (689,'Weird','weird','Illusion','Phantasm','Fear, Mind-Affecting',NULL,'Sorcerer/Wizard 9','V, S','1 standard action','Medium (100 ft. + 10 ft./level)','Any number of creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will disbelief (if interacted with), then Fortitude partial; see text','Yes','As phantasmal killer, but affects all within 30 ft.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>phantasmal killer</i>, except it can affect more than one creature. Only the affected creatures see the phantasmal creatures attacking them, though you see the attackers as shadowy shapes.</p>\n      <p>If a subject\'s Fortitude save succeeds, it still takes 3d6 points of damage and is stunned for 1 round. The subject also takes 1d4 points of temporary Strength damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Weird\" level=\"5\"><p><h5>Weird</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Phantasm) [Fear, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Any number of creatures, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>phantasmal killer</i>, except it can affect more than one creature. Only the affected creatures see the phantasmal creatures attacking them, though you see the attackers as shadowy shapes.</p><p>If a subject\'s Fortitude save succeeds, it still takes 3d6 points of damage and is stunned for 1 round. The subject also takes 1d4 points of temporary Strength damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (690,'Whirlwind','whirlwind','Evocation',NULL,'Air',NULL,'Air 8, Druid 8','V, S, DF','1 standard action','Long (400 ft. + 40 ft./level)',NULL,NULL,'Cyclone 10 ft. wide at base, 30 ft. wide at top, and 30 ft. tall','1 round/level (D)','Reflex negates; see text','Yes','Cyclone deals damage and can pick up creatures.',NULL,NULL,NULL,NULL,'\n      <p>This spell creates a powerful cyclone of raging wind that moves through the air, along the ground, or over water at a speed of 60 feet per round. You can concentrate on controlling the cyclone\'s every movement or specify a simple program. Directing the cyclone\'s movement or changing its programmed movement is a standard action for you. The cyclone always moves during your turn. If the cyclone exceeds the spell\'s range, it moves in a random, uncontrolled fashion for 1d3 rounds and then dissipates. (You can\'t regain control of the cyclone, even if comes back within range.)</p>\n      <p>Any Large or smaller creature that comes in contact with the spell effect must succeed on a Reflex save or take 3d6 points of damage. A Medium or smaller creature that fails its first save must succeed on a second one or be picked up bodily by the cyclone and held suspended in its powerful winds, taking 1d8 points of damage each round on your turn with no save allowed. You may direct the cyclone to eject any carried creatures whenever you wish, depositing the hapless souls wherever the cyclone happens to be when they are released.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Whirlwind\" level=\"5\"><p><h5>Whirlwind</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Air]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Air 8, Druid 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Cyclone 10 ft. wide at base, 30 ft. wide at top, and 30 ft. tall<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell creates a powerful cyclone of raging wind that moves through the air, along the ground, or over water at a speed of 60 feet per round. You can concentrate on controlling the cyclone\'s every movement or specify a simple program. Directing the cyclone\'s movement or changing its programmed movement is a standard action for you. The cyclone always moves during your turn. If the cyclone exceeds the spell\'s range, it moves in a random, uncontrolled fashion for 1d3 rounds and then dissipates. (You can\'t regain control of the cyclone, even if comes back within range.)</p><p>Any Large or smaller creature that comes in contact with the spell effect must succeed on a Reflex save or take 3d6 points of damage. A Medium or smaller creature that fails its first save must succeed on a second one or be picked up bodily by the cyclone and held suspended in its powerful winds, taking 1d8 points of damage each round on your turn with no save allowed. You may direct the cyclone to eject any carried creatures whenever you wish, depositing the hapless souls wherever the cyclone happens to be when they are released.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (691,'Whispering Wind','whispering wind','Transmutation',NULL,'Air',NULL,'Bard 2, Sorcerer/Wizard 2','V, S','1 standard action','1 mile/level',NULL,'10-ft. -radius spread',NULL,'No more than 1 hour/level or until discharged (destination is reached)','None','No','Sends a short message 1 mile/level.',NULL,NULL,NULL,NULL,'\n      <p>You send a message or sound on the wind to a designated spot. The <i>whispering wind</i> travels to a specific location within range that is familiar to you, provided that it can find a way to the location. A <i>whispering wind</i> is as gentle and unnoticed as a zephyr until it reaches the location. It then delivers its whisper-quiet message or other sound. Note that the message is delivered regardless of whether anyone is present to hear it. The wind then dissipates.</p>\n      <p>You can prepare the spell to bear a message of no more than twenty-five words, cause the spell to deliver other sounds for 1 round, or merely have the <i>whispering wind</i> seem to be a faint stirring of the air. You can likewise cause the <i>whispering wind</i> to move as slowly as 1 mile per hour or as quickly as 1 mile per 10 minutes.</p>\n      <p>When the spell reaches its objective, it swirls and remains in place until the message is delivered. As with <i>magic mouth</i>,  <i>whispering wind</i> cannot speak verbal components, use command words, or activate magical effects.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Whispering Wind\" level=\"5\"><p><h5>Whispering Wind</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Air]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>1 mile/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>No more than 1 hour/level or until discharged (destination is reached)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You send a message or sound on the wind to a designated spot. The <i>whispering wind</i> travels to a specific location within range that is familiar to you, provided that it can find a way to the location. A <i>whispering wind</i> is as gentle and unnoticed as a zephyr until it reaches the location. It then delivers its whisper-quiet message or other sound. Note that the message is delivered regardless of whether anyone is present to hear it. The wind then dissipates.</p><p>You can prepare the spell to bear a message of no more than twenty-five words, cause the spell to deliver other sounds for 1 round, or merely have the <i>whispering wind</i> seem to be a faint stirring of the air. You can likewise cause the <i>whispering wind</i> to move as slowly as 1 mile per hour or as quickly as 1 mile per 10 minutes.</p><p>When the spell reaches its objective, it swirls and remains in place until the message is delivered. As with <i>magic mouth</i>,  <i>whispering wind</i> cannot speak verbal components, use command words, or activate magical effects.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (692,'Wind Walk','wind walk','Transmutation',NULL,'Air',NULL,'Cleric 6, Druid 7','V, S, DF','1 standard action','Touch','You and one touched creature per three levels',NULL,NULL,'1 hour/level (D); see text','No and Will negates (harmless)','No and Yes (harmless)','You and your allies turn vaporous and travel fast.',NULL,NULL,NULL,NULL,'\n      <p>You alter the substance of your body to a cloudlike vapor (as the <i>gaseous form</i> spell) and move through the air, possibly at great speed. You can take other creatures with you, each of which acts independently.</p>\n      <p>Normally, a <i>wind walker</i> flies at a speed of 10 feet with perfect maneuverability. If desired by the subject, a magical wind wafts a <i>wind walker</i> along at up to 600 feet per round (60 mph) with poor maneuverability. <i>Wind walkers</i> are not invisible but rather appear misty and translucent. If fully clothed in white, they are 80% likely to be mistaken for clouds, fog, vapors, or the like.</p>\n      <p>A <i>wind walker</i> can regain its physical form as desired and later resume the cloud form. Each change to and from vaporous form takes 5 rounds, which counts toward the duration of the spell (as does any time spent in physical form). As noted above, you can dismiss the spell, and you can even dismiss it for individual wind walkers and not others.</p>\n      <p>For the last minute of the spell\'s duration, a <i>wind walker</i> in cloud form automatically descends 60 feet per round (for a total of 600 feet), though it may descend faster if it wishes. This descent serves as a warning that the spell is about to end.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wind Walk\" level=\"5\"><p><h5>Wind Walk</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Air]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Druid 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>You and one touched creature per three levels<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>No and Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No and Yes (harmless)<br/></td></tr></table><p>You alter the substance of your body to a cloudlike vapor (as the <i>gaseous form</i> spell) and move through the air, possibly at great speed. You can take other creatures with you, each of which acts independently.</p><p>Normally, a <i>wind walker</i> flies at a speed of 10 feet with perfect maneuverability. If desired by the subject, a magical wind wafts a <i>wind walker</i> along at up to 600 feet per round (60 mph) with poor maneuverability. <i>Wind walkers</i> are not invisible but rather appear misty and translucent. If fully clothed in white, they are 80% likely to be mistaken for clouds, fog, vapors, or the like.</p><p>A <i>wind walker</i> can regain its physical form as desired and later resume the cloud form. Each change to and from vaporous form takes 5 rounds, which counts toward the duration of the spell (as does any time spent in physical form). As noted above, you can dismiss the spell, and you can even dismiss it for individual wind walkers and not others.</p><p>For the last minute of the spell\'s duration, a <i>wind walker</i> in cloud form automatically descends 60 feet per round (for a total of 600 feet), though it may descend faster if it wishes. This descent serves as a warning that the spell is about to end.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (693,'Wind Wall','wind wall','Evocation',NULL,'Air',NULL,'Air 2, Cleric 3, Druid 3, Ranger 2, Sorcerer/Wizard 3','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Wall up to 10 ft./level long and 5 ft./level high (S)','1 round/level','None; see text','Yes','Deflects arrows, smaller creatures, and gases.',NULL,NULL,'A tiny fan and a feather of exotic origin.',NULL,'\n      <p>An invisible vertical curtain of wind appears. It is 2 feet thick and of considerable strength. It is a roaring blast sufficient to blow away any bird smaller than an eagle, or tear papers and similar materials from unsuspecting hands. (A Reflex save allows a creature to maintain its grasp on an object.) Tiny and Small flying creatures cannot pass through the barrier. Loose materials and cloth garments fly upward when caught in a <i>wind wall</i>. Arrows and bolts are deflected upward and miss, while any other normal ranged weapon passing through the wall has a 30% miss chance. (A giant-thrown boulder, a siege engine projectile, and other massive ranged weapons are not affected.) Gases, most gaseous breath weapons, and creatures in gaseous form cannot pass through the wall (although it is no barrier to incorporeal creatures).</p>\n      <p>While the wall must be vertical, you can shape it in any continuous path along the ground that you like. It is possible to create cylindrical or square wind walls to enclose specific points.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wind Wall\" level=\"5\"><p><h5>Wind Wall</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Air]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Air 2, Cleric 3, Druid 3, Ranger 2, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Wall up to 10 ft./level long and 5 ft./level high (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>An invisible vertical curtain of wind appears. It is 2 feet thick and of considerable strength. It is a roaring blast sufficient to blow away any bird smaller than an eagle, or tear papers and similar materials from unsuspecting hands. (A Reflex save allows a creature to maintain its grasp on an object.) Tiny and Small flying creatures cannot pass through the barrier. Loose materials and cloth garments fly upward when caught in a <i>wind wall</i>. Arrows and bolts are deflected upward and miss, while any other normal ranged weapon passing through the wall has a 30% miss chance. (A giant-thrown boulder, a siege engine projectile, and other massive ranged weapons are not affected.) Gases, most gaseous breath weapons, and creatures in gaseous form cannot pass through the wall (although it is no barrier to incorporeal creatures).</p><p>While the wall must be vertical, you can shape it in any continuous path along the ground that you like. It is possible to create cylindrical or square wind walls to enclose specific points.</p><p><i>Arcane Material Component:</i> A tiny fan and a feather of exotic origin.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (694,'Wish','wish','Universal',NULL,NULL,NULL,'Sorcerer/Wizard 9','V, XP','1 standard action','See text','See text','See text','See text','See text','See text','Yes','As limited wish, but with fewer limits.',NULL,'When a Wish duplicates a spell with a material component that costs more than 10,000 gp, you must provide that component.',NULL,NULL,'\n      <p><i>Wish</i> is the mightiest spell a wizard or sorcerer can cast. By simply speaking aloud, you can alter reality to better suit you.</p>\n      <p>Even <i>wish</i>, however, has its limits.</p>\n      <p>A <i>Wish</i> can produce any one of the following effects.</p>\n      <ul>\n <li> Duplicate any wizard or sorcerer spell of 8th level or lower, provided the spell is not of a school prohibited to you.</li>\n <li> Duplicate any other spell of 6th level or lower, provided the spell is not of a school prohibited to you.</li>\n <li> Duplicate any wizard or sorcerer spell of 7th level or lower even if it\'s of a prohibited school.</li>\n <li> Duplicate any other spell of 5th level or lower even if it\'s of a prohibited school.</li>\n <li> Undo the harmful effects of many other spells, such as <i>geas/quest</i> or <i>insanity</i>.</li>\n <li> Create a nonmagical item of up to 25,000 gp in value.</li>\n <li> Create a magic item, or add to the powers of an existing magic item.</li>\n <li> Grant a creature a +1 inherent bonus to an ability score. Two to five <i>Wish</i> spells cast in immediate succession can grant a creature a +2 to +5 inherent bonus to an ability score (two wishes for a +2 inherent bonus, three for a +3 inherent bonus, and so on). Inherent bonuses are instantaneous, so they cannot be dispelled. <i>Note:</i> An inherent bonus may not exceed +5 for a single ability score, and inherent bonuses to a particular ability score do not stack, so only the best one applies.</li>\n <li> Remove injuries and afflictions. A single <i>Wish</i> can aid one creature per caster level, and all subjects are cured of the same kind of affliction. For example, you could heal all the damage you and your companions have taken, or remove all poison effects from everyone in the party, but not do both with the same <i>wish</i>. A <i>Wish</i> can never restore the experience point loss from casting a spell or the level or Constitution loss from being raised from the dead.</li>\n <li> Revive the dead. A <i>Wish</i> can bring a dead creature back to life by duplicating a <i>resurrection</i> spell. A <i>Wish</i> can revive a dead creature whose body has been destroyed, but the task takes two <i>wishes</i>,  one to recreate the body and another to infuse the body with life again. A <i>Wish</i> cannot prevent a character who was brought back to life from losing an experience level.</li>\n <li> Transport travelers. A <i>Wish</i> can lift one creature per caster level from anywhere on any plane and place those creatures anywhere else on any plane regardless of local conditions. An unwilling target gets a Will save to negate the effect, and spell resistance (if any) applies.</li>\n <li> Undo misfortune. A <i>Wish</i> can undo a single recent event. The <i>Wish</i> forces a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a <i>Wish</i> could undo an opponent\'s successful save, a foe\'s successful critical hit (either the attack roll or the critical roll), a friend\'s failed save, and so on. The reroll, however, may be as bad as or worse than the original roll. An unwilling target gets a Will save to negate the effect, and spell resistance (if any) applies.</li>\n</ul>\n      <p>You may try to use a <i>Wish</i> to produce greater effects than these, but doing so is dangerous. (The <i>Wish</i> may pervert your intent into a literal but undesirable fulfillment or only a partial fulfillment.)</p>\n      <p>Duplicated spells allow saves and spell resistance as normal (but save DCs are for 9th-level spells).</p>\n      <p/>\n    ','The minimum XP cost for casting Wish is 5,000 XP. When a Wish duplicates a spell that has an XP cost, you must pay 5,000 XP or that cost, whichever is more. When a Wish creates or improves a magic item, you must pay twice the normal XP cost for crafting or improving the item, plus an additional 5,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wish\" level=\"5\"><p><h5>Wish</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Universal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target, Effect, or Area:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p><i>Wish</i> is the mightiest spell a wizard or sorcerer can cast. By simply speaking aloud, you can alter reality to better suit you.</p><p>Even <i>wish</i>, however, has its limits.</p><p>A <i>Wish</i> can produce any one of the following effects.</p><ul>\n <li> Duplicate any wizard or sorcerer spell of 8th level or lower, provided the spell is not of a school prohibited to you.</li>\n <li> Duplicate any other spell of 6th level or lower, provided the spell is not of a school prohibited to you.</li>\n <li> Duplicate any wizard or sorcerer spell of 7th level or lower even if it\'s of a prohibited school.</li>\n <li> Duplicate any other spell of 5th level or lower even if it\'s of a prohibited school.</li>\n <li> Undo the harmful effects of many other spells, such as <i>geas/quest</i> or <i>insanity</i>.</li>\n <li> Create a nonmagical item of up to 25,000 gp in value.</li>\n <li> Create a magic item, or add to the powers of an existing magic item.</li>\n <li> Grant a creature a +1 inherent bonus to an ability score. Two to five <i>Wish</i> spells cast in immediate succession can grant a creature a +2 to +5 inherent bonus to an ability score (two wishes for a +2 inherent bonus, three for a +3 inherent bonus, and so on). Inherent bonuses are instantaneous, so they cannot be dispelled. <i>Note:</i> An inherent bonus may not exceed +5 for a single ability score, and inherent bonuses to a particular ability score do not stack, so only the best one applies.</li>\n <li> Remove injuries and afflictions. A single <i>Wish</i> can aid one creature per caster level, and all subjects are cured of the same kind of affliction. For example, you could heal all the damage you and your companions have taken, or remove all poison effects from everyone in the party, but not do both with the same <i>wish</i>. A <i>Wish</i> can never restore the experience point loss from casting a spell or the level or Constitution loss from being raised from the dead.</li>\n <li> Revive the dead. A <i>Wish</i> can bring a dead creature back to life by duplicating a <i>resurrection</i> spell. A <i>Wish</i> can revive a dead creature whose body has been destroyed, but the task takes two <i>wishes</i>,  one to recreate the body and another to infuse the body with life again. A <i>Wish</i> cannot prevent a character who was brought back to life from losing an experience level.</li>\n <li> Transport travelers. A <i>Wish</i> can lift one creature per caster level from anywhere on any plane and place those creatures anywhere else on any plane regardless of local conditions. An unwilling target gets a Will save to negate the effect, and spell resistance (if any) applies.</li>\n <li> Undo misfortune. A <i>Wish</i> can undo a single recent event. The <i>Wish</i> forces a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a <i>Wish</i> could undo an opponent\'s successful save, a foe\'s successful critical hit (either the attack roll or the critical roll), a friend\'s failed save, and so on. The reroll, however, may be as bad as or worse than the original roll. An unwilling target gets a Will save to negate the effect, and spell resistance (if any) applies.</li>\n</ul><p>You may try to use a <i>Wish</i> to produce greater effects than these, but doing so is dangerous. (The <i>Wish</i> may pervert your intent into a literal but undesirable fulfillment or only a partial fulfillment.)</p><p>Duplicated spells allow saves and spell resistance as normal (but save DCs are for 9th-level spells).</p><p><i>Material Component:</i> When a <i>Wish</i> duplicates a spell with a material component that costs more than 10,000 gp, you must provide that component.</p><p><i>XP Cost:</i> The minimum XP cost for casting <i>Wish</i> is 5,000 XP. When a <i>Wish</i> duplicates a spell that has an XP cost, you must pay 5,000 XP or that cost, whichever is more. When a <i>Wish</i> creates or improves a magic item, you must pay twice the normal XP cost for crafting or improving the item, plus an additional 5,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (695,'Wood Shape','wood shape','Transmutation',NULL,NULL,NULL,'Druid 2','V, S, DF','1 standard action','Touch','One touched piece of wood no larger than 10 cu. ft. + 1 cu. ft./level',NULL,NULL,'Instantaneous','Will negates (object)','Yes (object)','Rearranges wooden objects to suit you.',NULL,NULL,NULL,NULL,'\n      <p>W<i>ood shape</i> enables you to form one existing piece of wood into any shape that suits your purpose. While it is possible to make crude coffers, doors, and so forth, fine detail isn\'t possible. There is a 30% chance that any shape that includes moving parts simply doesn\'t work.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Wood Shape\" level=\"5\"><p><h5>Wood Shape</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One touched piece of wood no larger than 10 cu. ft. + 1 cu. ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>W<i>ood shape</i> enables you to form one existing piece of wood into any shape that suits your purpose. While it is possible to make crude coffers, doors, and so forth, fine detail isn\'t possible. There is a 30% chance that any shape that includes moving parts simply doesn\'t work.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (696,'Word of Chaos','word of chaos','Evocation',NULL,'Chaotic, Sonic',NULL,'Chaos 7, Cleric 7','V','1 standard action','40 ft.',NULL,'Nonchaotic creatures in a 40-ft. - radius spread centered on you',NULL,'Instantaneous','None or Will negates; see text','Yes','Kills, confuses, stuns, or deafens nonchaotic subjects.',NULL,NULL,NULL,NULL,'\n      <p>Any nonchaotic creature within the area who hears the <i>word of chaos</i> suffers the following ill effects.</p>\n      <p>The effects are cumulative and concurrent. No saving throw is allowed against these effects.</p>\n      <p><i>Deafened:</i> The creature is deafened for 1d4 rounds.</p>\n      <p><i>Stunned:</i> The creature is stunned for 1 round.</p>\n      <p><i>Confused:</i> The creature is <i>confused</i>,  as by the <i>confusion</i> spell, for 1d10 minutes. This is a mind-affecting enchantment effect.</p>\n      <p><i>Killed:</i> Living creatures die. Undead creatures are destroyed.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>HD</b><br/></td> <td><b>Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Equal to caster level<br/></td>\n<td>Deafened<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -1<br/></td>\n<td>Stunned, deafened<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -5<br/></td>\n<td><i>confused</i>, stunned, deafened<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -10<br/></td>\n<td>Killed, <i>confused</i>, stunned, deafened<br/></td>\n\n</tr>\n</table>\n      <p>Furthermore, if you are on your home plane when you cast this spell, nonchaotic extraplanar creatures within the area are instantly banished back to their home planes. Creatures so banished cannot return for at least 24 hours. This effect takes place regardless of whether the creatures hear the <i>word of chaos</i>. The banishment effect allows a Will save (at a -4 penalty) to negate.</p>\n      <p>Creatures whose HD exceed your caster level are unaffected by <i>word of chaos</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Word of Chaos\" level=\"5\"><p><h5>Word of Chaos</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Chaotic, Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Chaos 7, Cleric 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>40 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Nonchaotic creatures in a 40-ft. - radius spread centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Any nonchaotic creature within the area who hears the <i>word of chaos</i> suffers the following ill effects.</p><p>The effects are cumulative and concurrent. No saving throw is allowed against these effects.</p><p><i>Deafened:</i> The creature is deafened for 1d4 rounds.</p><p><i>Stunned:</i> The creature is stunned for 1 round.</p><p><i>Confused:</i> The creature is <i>confused</i>,  as by the <i>confusion</i> spell, for 1d10 minutes. This is a mind-affecting enchantment effect.</p><p><i>Killed:</i> Living creatures die. Undead creatures are destroyed.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>HD</b><br/></td> <td><b>Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Equal to caster level<br/></td>\n<td>Deafened<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -1<br/></td>\n<td>Stunned, deafened<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -5<br/></td>\n<td><i>confused</i>, stunned, deafened<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -10<br/></td>\n<td>Killed, <i>confused</i>, stunned, deafened<br/></td>\n\n</tr>\n</table><p>Furthermore, if you are on your home plane when you cast this spell, nonchaotic extraplanar creatures within the area are instantly banished back to their home planes. Creatures so banished cannot return for at least 24 hours. This effect takes place regardless of whether the creatures hear the <i>word of chaos</i>. The banishment effect allows a Will save (at a -4 penalty) to negate.</p><p>Creatures whose HD exceed your caster level are unaffected by <i>word of chaos</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (697,'Word of Recall','word of recall','Conjuration','Teleportation',NULL,NULL,'Cleric 6, Druid 8','V','1 standard action','Unlimited','You and touched objects or other willing creatures',NULL,NULL,'Instantaneous','None or Will negates (harmless, object)','No or Yes (harmless, object)','Teleports you back to designated place.',NULL,NULL,NULL,NULL,'\n      <p><i>Word of recall</i> teleports you instantly back to your sanctuary when the word is uttered. You must designate the sanctuary when you prepare the spell, and it must be a very familiar place. The actual point of arrival is a designated area no larger than 10 feet by 10 feet. You can be transported any distance within a plane but cannot travel between planes. You can transport, in addition to yourself, any objects you carry, as long as their weight doesn\'t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. Exceeding this limit causes the spell to fail.</p>\n      <p>An unwilling creature can\'t be teleported by <i>word of recall</i>. Likewise, a creature\'s Will save (or spell resistance) prevents items in its possession from being teleported. Unattended, nonmagical objects receive no saving throw.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Word of Recall\" level=\"5\"><p><h5>Word of Recall</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Druid 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Unlimited<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You and touched objects or other willing creatures<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No or Yes (harmless, object)<br/></td></tr></table><p><i>Word of recall</i> teleports you instantly back to your sanctuary when the word is uttered. You must designate the sanctuary when you prepare the spell, and it must be a very familiar place. The actual point of arrival is a designated area no larger than 10 feet by 10 feet. You can be transported any distance within a plane but cannot travel between planes. You can transport, in addition to yourself, any objects you carry, as long as their weight doesn\'t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. Exceeding this limit causes the spell to fail.</p><p>An unwilling creature can\'t be teleported by <i>word of recall</i>. Likewise, a creature\'s Will save (or spell resistance) prevents items in its possession from being teleported. Unattended, nonmagical objects receive no saving throw.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (698,'Zone of Silence','zone of silence','Illusion','Glamer',NULL,NULL,'Bard 4','V, S','1 round','Personal',NULL,'5-ft. -radius emanation centered on you',NULL,'1 hour/level (D)',NULL,NULL,'Keeps eavesdroppers from overhearing conversations.',NULL,NULL,NULL,NULL,'\n      <p>By casting <i>zone of silence</i>, you manipulate sound waves in your immediate vicinity so that you and those within the spell\'s area can converse normally, yet no one outside can hear your voices or any other noises from within, including language-dependent or sonic spell effects. This effect is centered on you and moves with you. Anyone who enters the zone immediately becomes subject to its effects, but those who leave are no longer affected. Note, however, that a successful Spot check to read lips can still reveal what\'s said inside a <i>zone of silence</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Zone of Silence\" level=\"5\"><p><h5>Zone of Silence</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>5-ft. -radius emanation centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr></table><p>By casting <i>zone of silence</i>, you manipulate sound waves in your immediate vicinity so that you and those within the spell\'s area can converse normally, yet no one outside can hear your voices or any other noises from within, including language-dependent or sonic spell effects. This effect is centered on you and moves with you. Anyone who enters the zone immediately becomes subject to its effects, but those who leave are no longer affected. Note, however, that a successful Spot check to read lips can still reveal what\'s said inside a <i>zone of silence</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
INSERT INTO spell VALUES (699,'Zone of Truth','zone of truth','Enchantment','Compulsion','Mind-Affecting',NULL,'Cleric 2, Paladin 2','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'20-ft. -radius emanation',NULL,'1 min./level','Will negates','Yes','Subjects within range cannot lie.',NULL,NULL,NULL,NULL,'\n      <p>Creatures within the emanation area (or those who enter it) can\'t speak any deliberate and intentional lies. Each potentially affected creature is allowed a save to avoid the effects when the spell is cast or when the creature first enters the emanation area. Affected creatures are aware of this enchantment. Therefore, they may avoid answering questions to which they would normally respond with a lie, or they may be evasive as long as they remain within the boundaries of the truth. Creatures who leave the area are free to speak as they choose.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Zone of Truth\" level=\"5\"><p><h5>Zone of Truth</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Paladin 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Creatures within the emanation area (or those who enter it) can\'t speak any deliberate and intentional lies. Each potentially affected creature is allowed a save to avoid the effects when the spell is cast or when the creature first enters the emanation area. Affected creatures are aware of this enchantment. Therefore, they may avoid answering questions to which they would normally respond with a lie, or they may be evasive as long as they remain within the boundaries of the truth. Creatures who leave the area are free to speak as they choose.</p><p/>\n</div>\n    ','SRD 3.5 SpellsT-Z');
